(()=>{
  if(window.__backendFastApiAdded)return;
  window.__backendFastApiAdded=true;

  const terminal=text=>`<pre style="padding:18px;border-radius:12px;background:#07111f;color:#86efac;font-family:ui-monospace,monospace">${text}</pre>`;
  const response=(method,path,status,body)=>`<section style="font-family:system-ui;border:1px solid #cbd5e1;border-radius:12px;overflow:hidden"><header style="padding:10px 14px;background:#0f172a;color:white"><strong style="color:#4ade80">${method}</strong> ${path} · ${status}</header><pre style="margin:0;padding:16px;background:white;color:#334155">${body}</pre></section>`;
  const B=(topic,name,description,code,preview,tip)=>T(topic,name,description,code,preview,[],{kind:'Backend FastAPI',tip});
  const add=(title,description,quote,challenge,items)=>sections.push({title,description,quote,challenge,items});

  add('Backend FastAPI · Introducción','Comprende cómo funciona un backend, qué responsabilidades asume FastAPI y cómo PostgreSQL conserva los datos de una aplicación.','“La API define el contrato; la base de datos protege el estado; el backend conecta ambos con reglas de negocio.”','Dibuja el recorrido completo de una solicitud desde el frontend hasta PostgreSQL.',[
    B('Arquitectura','¿Qué hace el backend?','El backend recibe solicitudes HTTP, valida datos, aplica reglas de negocio, consulta o modifica información y devuelve respuestas. FastAPI atiende la capa HTTP; Pydantic valida el contrato; SQLAlchemy construye operaciones de persistencia; Psycopg comunica Python con PostgreSQL.','Frontend\n   ↓ HTTP + JSON\nFastAPI → validación → servicio → SQLAlchemy\n                                  ↓\n                              PostgreSQL\n   ↑ respuesta JSON','<div style="font-family:system-ui;text-align:center"><strong>Cliente → API → lógica → base de datos → respuesta</strong></div>','No permitas que el frontend se conecte directamente a PostgreSQL.'),
    B('HTTP','Recursos, métodos y estados','Una API orientada a recursos utiliza URLs con sustantivos y métodos HTTP con intención clara. GET consulta, POST crea, PATCH modifica parcialmente y DELETE elimina. Los códigos 200, 201, 204, 400, 401, 403, 404, 409 y 422 comunican el resultado sin depender solamente del cuerpo.','GET    /api/v1/products        → listar\nGET    /api/v1/products/42     → consultar\nPOST   /api/v1/products        → crear\nPATCH  /api/v1/products/42     → actualizar\nDELETE /api/v1/products/42     → eliminar','<table style="width:100%;font-family:system-ui"><tr><th>Método</th><th>Uso</th></tr><tr><td>GET</td><td>Leer</td></tr><tr><td>POST</td><td>Crear</td></tr><tr><td>PATCH</td><td>Modificar</td></tr><tr><td>DELETE</td><td>Eliminar</td></tr></table>','Diseña primero el contrato de recursos, respuestas y errores.'),
    B('Capas','Responsabilidades del proyecto','Las rutas traducen HTTP; los schemas validan entrada y salida; los modelos representan tablas; los servicios contienen reglas de negocio; la configuración obtiene valores del entorno; las dependencias entregan recursos como sesiones y usuarios. Separar estas responsabilidades evita endpoints enormes y facilita pruebas.','router → recibe HTTP y devuelve respuesta\nschema → valida y documenta datos\nservice → aplica reglas de negocio\nmodel → representa persistencia\ndatabase → configura engine y sesiones\nconfig → lee el entorno','<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;font-family:system-ui;text-align:center"><span>Router</span><span>Servicio</span><span>Modelo</span><span>Schema</span><span>DB</span><span>Config</span></div>','Empieza con pocas capas y extrae reglas cuando aparezcan; no dupliques consultas en cada endpoint.'),
    B('Ruta','Orden de aprendizaje','La ruta comienza con Python y un endpoint sin base de datos. Después crea PostgreSQL, configura SQLAlchemy, define modelo y schemas, aplica migraciones y construye el CRUD. Seguridad, pruebas, CORS, registros y despliegue se añaden cuando el flujo principal ya funciona.','1. Python y entorno virtual\n2. Primer endpoint FastAPI\n3. Configuración y estructura\n4. PostgreSQL y conexión\n5. Modelos y migraciones\n6. CRUD y reglas\n7. Seguridad, pruebas y producción','<ol style="font-family:system-ui;line-height:1.8"><li>Preparar</li><li>Crear API</li><li>Conectar PostgreSQL</li><li>Construir CRUD</li><li>Proteger y desplegar</li></ol>','Ejecuta cada ejemplo antes de continuar y conserva las migraciones en Git.')
  ]);

  add('Backend FastAPI · Caso cotidiano','Sigue una tienda de barrio que usa FastAPI y PostgreSQL para consultar productos, registrar mercancía y vender sin perder el control del inventario.','“La API funciona como el encargado que recibe una petición, revisa las reglas y actualiza el cuaderno digital de la tienda.”','Explica qué ocurre desde que Ana vende dos panes hasta que el nuevo stock aparece en pantalla.',[
    B('Historia','La tienda de Ana','Ana tiene una tienda y actualmente anota productos, precios y existencias en un cuaderno. Cuando vende algo debe restar unidades; cuando llega mercancía debe aumentar el stock; si alguien pregunta por un producto necesita encontrarlo rápidamente. La aplicación convertirá esas tareas cotidianas en operaciones de una API.','Cuaderno actual:\nPan       $2.000   20 unidades\nLeche     $4.500   12 unidades\nCafé      $8.000    6 unidades\n\nProblemas:\n- cuentas manuales\n- datos repetidos\n- no hay historial\n- dos personas pueden anotar valores distintos','<section style="font-family:system-ui;padding:18px;border:1px solid #d6d3d1;background:#fffbeb"><h2>Inventario de Ana</h2><p>Pan: 20 · Leche: 12 · Café: 6</p></section>','Relaciona cada necesidad del negocio con una operación antes de pensar en tablas o código.'),
    B('Analogía','FastAPI como encargado del mostrador','El cliente no entra a la bodega ni modifica el cuaderno. Entrega una solicitud al encargado: “muéstrame el pan” o “registra esta venta”. FastAPI recibe la solicitud, comprueba que tenga datos válidos, llama la regla correspondiente y entrega una respuesta. PostgreSQL es el inventario confiable guardado detrás del mostrador.','Cliente: “Quiero comprar 2 panes”\n        ↓ POST /sales\nFastAPI: “¿La petición es válida?”\n        ↓ servicio\nRegla: “¿Hay al menos 2 panes?”\n        ↓ transacción\nPostgreSQL: stock 20 → 18\n        ↑\nRespuesta: “Venta registrada”','<div style="font-family:system-ui;text-align:center"><strong>Cliente → encargado FastAPI → inventario PostgreSQL</strong></div>','La analogía explica responsabilidades, pero cada validación crítica debe existir realmente en el código y la base.'),
    B('Datos','Del cuaderno a las tablas','products representa cada artículo una sola vez. sales registra la venta completa y sale_items conserva qué productos y cantidades incluyó. Las claves primarias identifican filas y las foráneas relacionan el detalle con su venta y producto. El precio unitario se copia en el detalle para conservar el valor histórico aunque luego cambie.','products\n1 | PAN-01 | Pan   | 2000 | stock 20\n2 | LEC-01 | Leche | 4500 | stock 12\n\nsales\n15 | 2026-09-06 | total 8500\n\nsale_items\n15 | product 1 | quantity 2 | unit_price 2000\n15 | product 2 | quantity 1 | unit_price 4500','<table style="width:100%;font-family:system-ui"><caption>Venta 15</caption><tr><th>Producto</th><th>Cantidad</th><th>Subtotal</th></tr><tr><td>Pan</td><td>2</td><td>$4.000</td></tr><tr><td>Leche</td><td>1</td><td>$4.500</td></tr></table>','Guarda hechos históricos de la venta; no los recalcules usando precios actuales.'),
    B('Consultar','Buscar productos: GET','Cuando Ana abre el inventario, el frontend solicita GET /products. FastAPI recibe búsqueda y paginación, SQLAlchemy genera una consulta y PostgreSQL devuelve filas ordenadas. Pydantic forma la respuesta pública. GET no modifica datos, por lo que puede repetirse sin cambiar el inventario.','@router.get("/products", response_model=ProductPage)\ndef list_products(db: DbSession, q: str | None = None):\n    statement = select(Product).order_by(Product.name)\n    if q:\n        statement = statement.where(Product.name.ilike(f"%{q}%"))\n    items = db.scalars(statement.limit(20)).all()\n    return {"items": items, "total": len(items), "limit": 20, "offset": 0}',response('GET','/api/v1/products?q=pan','200','{\n  "items": [\n    {"id": 1, "name": "Pan", "price": "2000.00", "stock": 20}\n  ],\n  "total": 1\n}'),'El ejemplo simplifica total; en datos paginados reales cuenta con una consulta apropiada.'),
    B('Crear','Registrar mercancía: POST','Llega un producto nuevo llamado Chocolate. El formulario envía JSON a POST /products. Pydantic rechaza nombre corto, precio negativo o stock menor que cero. El servicio crea el modelo, PostgreSQL asigna el identificador y la API responde 201 con el artículo persistido.','POST /api/v1/products\nContent-Type: application/json\n\n{\n  "sku": "CHO-01",\n  "name": "Chocolate",\n  "price": "3500.00",\n  "stock": 10\n}\n\n# FastAPI\n@router.post("/products", response_model=ProductRead, status_code=201)\ndef create(data: ProductCreate, db: DbSession):\n    return product_service.create(db, data)',response('POST','/api/v1/products','201','{\n  "id": 3,\n  "sku": "CHO-01",\n  "name": "Chocolate",\n  "price": "3500.00",\n  "stock": 10\n}'),'Intenta enviar stock -1 en /docs para observar la respuesta 422 antes de llegar a PostgreSQL.'),
    B('Actualizar','Corregir precio: PATCH','Ana descubre que el precio de la leche ahora es 4.700. PATCH envía solamente price; no reemplaza nombre, SKU ni stock. FastAPI valida el valor, el servicio localiza el producto y SQLAlchemy ejecuta UPDATE dentro de una transacción. Si el id no existe, la API responde 404.','PATCH /api/v1/products/2\nContent-Type: application/json\n\n{ "price": "4700.00" }\n\nchanges = data.model_dump(exclude_unset=True)\nfor field, value in changes.items():\n    setattr(product, field, value)\ndb.commit()\ndb.refresh(product)',response('PATCH','/api/v1/products/2','200','{\n  "id": 2,\n  "name": "Leche",\n  "price": "4700.00",\n  "stock": 12\n}'),'Usa PATCH para cambios parciales y conserva fuera del schema campos que el cliente no puede editar.'),
    B('Venta','Vender sin dejar stock negativo','Un cliente compra dos panes y una leche. La regla consulta los productos, confirma disponibilidad, calcula subtotales con Decimal, crea la venta y descuenta existencias en una sola transacción. Si falta cualquier producto, rollback deja todo como estaba: no debe existir una venta cobrada a medias.','POST /api/v1/sales\n{\n  "items": [\n    {"product_id": 1, "quantity": 2},\n    {"product_id": 2, "quantity": 1}\n  ]\n}\n\nwith db.begin():\n    # bloquear o actualizar inventario de forma segura\n    # validar stock de cada producto\n    # crear sale y sale_items\n    # descontar 2 panes y 1 leche',response('POST','/api/v1/sales','201','{\n  "id": 15,\n  "total": "8700.00",\n  "status": "confirmed",\n  "remaining_stock": {"Pan": 18, "Leche": 11}\n}'),'Para ventas concurrentes utiliza bloqueo o actualización condicional; una lectura seguida de resta puede competir con otra solicitud.'),
    B('Recorrido','La compra completa paso a paso','El frontend desactiva el botón durante el envío y manda JSON. FastAPI valida cantidades, la dependencia abre una Session y el servicio inicia la transacción. PostgreSQL protege claves y stock, commit confirma todos los cambios, Pydantic limita la respuesta y FastAPI devuelve 201. Después el frontend muestra recibo y nuevas existencias.','1. Ana pulsa “Registrar venta”.\n2. POST /sales envía productos y cantidades.\n3. ProductSaleCreate valida quantity > 0.\n4. get_db entrega una Session.\n5. El servicio consulta y protege existencias.\n6. Crea sale y sale_items.\n7. Descuenta stock.\n8. COMMIT confirma todo.\n9. SaleRead produce JSON público.\n10. La pantalla muestra el recibo.','<section style="font-family:system-ui;padding:18px;border:1px solid #86efac;background:#f0fdf4"><h2>Venta #15 confirmada</h2><p>2 panes + 1 leche · Total $8.700</p><p>Stock actualizado correctamente.</p></section>','Prueba también cantidad cero, producto inexistente, stock insuficiente y error durante la transacción.')
  ]);

  add('Backend FastAPI · React + Tailwind','Construye la pantalla de la tienda de Ana con React, aplica el diseño mediante Tailwind CSS y conecta formularios e inventario con la API de FastAPI. Cada ejemplo muestra qué ve la persona y qué petición viaja al backend.','“React conserva el estado de la pantalla; Tailwind comunica visualmente ese estado; FastAPI valida y PostgreSQL conserva la verdad.”','Levanta frontend y backend, registra un producto y realiza una venta comprobando que el inventario se actualice.',[
    B('Arquitectura','Qué hace cada tecnología','Imagina la tienda como tres espacios. React es el mostrador que cambia cuando Ana busca o vende; Tailwind organiza letreros, colores, botones y distribución; FastAPI es el encargado que valida solicitudes y aplica reglas; PostgreSQL es la bodega que conserva productos, ventas y existencias. El navegador nunca debe conectarse directamente a la base de datos.','Ana pulsa “Vender”\n        ↓\nReact recoge carrito y cantidades\nTailwind muestra “Procesando...”\n        ↓ POST /api/v1/sales\nFastAPI valida y aplica la venta\n        ↓ transacción\nPostgreSQL descuenta existencias\n        ↑ JSON 201\nReact actualiza inventario y recibo','<div style="font-family:system-ui;padding:18px"><strong>React + Tailwind</strong> → <strong>FastAPI</strong> → <strong>PostgreSQL</strong></div>','Si una regla protege dinero o inventario, repítela o impónla en el backend; ocultar un botón en React no protege los datos.'),
    B('Carpetas','Estructura del proyecto completo','Separa frontend y backend para que cada herramienta conserve su configuración. En frontend, components contiene piezas visuales, services centraliza las llamadas HTTP y App.jsx coordina el caso de uso. En backend permanecen routers, schemas, services y modelos. Esta estructura permite localizar con rapidez dónde se dibuja, dónde se solicita y dónde se decide.','tienda-ana/\n├─ frontend/\n│  ├─ src/\n│  │  ├─ components/\n│  │  │  ├─ ProductList.jsx\n│  │  │  ├─ ProductForm.jsx\n│  │  │  └─ SaleForm.jsx\n│  │  ├─ services/api.js\n│  │  ├─ App.jsx\n│  │  └─ index.css\n│  ├─ .env.example\n│  ├─ package.json\n│  └─ vite.config.js\n└─ backend/\n   ├─ app/api/routes/\n   ├─ app/models/\n   ├─ app/schemas/\n   ├─ app/services/\n   ├─ migrations/\n   └─ tests/','<pre style="padding:16px;background:#0f172a;color:#bae6fd">tienda-ana\n├─ frontend  React + Tailwind\n└─ backend   FastAPI + PostgreSQL</pre>','Guarda en Git .env.example sin secretos; excluye .env, node_modules y .venv.'),
    B('Instalación','Crear React y agregar Tailwind','Vite crea el proyecto React y proporciona el servidor de desarrollo. Tailwind se instala con su plugin oficial de Vite y se importa en el CSS principal. La primera comprobación consiste en mostrar un título con utilidades visibles; así detectas una instalación incorrecta antes de sumar componentes o llamadas a la API.','npm create vite@latest frontend -- --template react\ncd frontend\nnpm install\nnpm install tailwindcss @tailwindcss/vite\n\n// vite.config.js\nimport { defineConfig } from "vite";\nimport react from "@vitejs/plugin-react";\nimport tailwindcss from "@tailwindcss/vite";\n\nexport default defineConfig({\n  plugins: [react(), tailwindcss()],\n});\n\n/* src/index.css */\n@import "tailwindcss";\n\nnpm run dev','<div style="font-family:system-ui;padding:24px;background:#f0fdfa;color:#115e59"><h2 style="font-size:26px">Tienda de Ana</h2><p>React y Tailwind están listos.</p></div>','Mantén import "./index.css" en main.jsx. Este ejemplo usa la integración actual de Tailwind con Vite.'),
    B('Conexión','Centralizar las llamadas a FastAPI','La dirección del backend pertenece a una variable de entorno porque cambia entre desarrollo y despliegue. request reúne fetch, encabezados JSON y lectura de errores para que los componentes no repitan esa lógica. Cuando FastAPI devuelve un detalle comprensible, React puede mostrarlo cerca de la acción que falló.','// frontend/.env\nVITE_API_URL=http://127.0.0.1:8000/api/v1\n\n// src/services/api.js\nconst API_URL = import.meta.env.VITE_API_URL;\n\nexport async function request(path, options = {}) {\n  const response = await fetch(API_URL + path, {\n    ...options,\n    headers: {\n      "Content-Type": "application/json",\n      ...options.headers,\n    },\n  });\n\n  if (!response.ok) {\n    const error = await response.json();\n    throw new Error(error.detail ?? "No se pudo completar la solicitud");\n  }\n  return response.json();\n}','<pre style="padding:16px;background:#0f172a;color:#86efac">frontend → http://127.0.0.1:8000/api/v1</pre>','VITE_API_URL es pública dentro del paquete del navegador: nunca guardes contraseñas o claves privadas allí.'),
    B('Inventario','Mostrar productos con React','ProductList recibe los productos como props y transforma cada fila en una tarjeta. La key permite a React identificar cada producto entre actualizaciones. Tailwind construye una cuadrícula adaptable: una columna en móvil y tres desde pantallas medianas. El botón informa su propósito y queda desactivado si no hay existencias.','// src/components/ProductList.jsx\nexport function ProductList({ products, onAdd }) {\n  return (\n    <section aria-labelledby="inventory-title">\n      <h2 id="inventory-title" className="mb-4 text-2xl font-bold text-slate-900">\n        Inventario\n      </h2>\n      <div className="grid gap-4 md:grid-cols-3">\n        {products.map((product) => (\n          <article key={product.id} className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200">\n            <h3 className="font-semibold">{product.name}</h3>\n            <p className="text-sm text-slate-600">Stock: {product.stock}</p>\n            <p className="mt-2 text-lg font-bold text-emerald-700">$ {product.price}</p>\n            <button disabled={!product.stock} onClick={() => onAdd(product)} className="mt-4 rounded-lg bg-emerald-600 px-4 py-2 text-white disabled:bg-slate-300">\n              Agregar\n            </button>\n          </article>\n        ))}\n      </div>\n    </section>\n  );\n}','<section style="font-family:system-ui;padding:18px;background:#f8fafc"><h2>Inventario</h2><div style="display:flex;gap:12px;flex-wrap:wrap"><article style="padding:14px;background:white;border:1px solid #cbd5e1;border-radius:14px"><b>Pan</b><p>Stock: 20 · $2.000</p><button style="background:#059669;color:white;border:0;padding:8px 14px;border-radius:8px">Agregar</button></article><article style="padding:14px;background:white;border:1px solid #cbd5e1;border-radius:14px"><b>Leche</b><p>Stock: 12 · $4.700</p><button style="background:#059669;color:white;border:0;padding:8px 14px;border-radius:8px">Agregar</button></article></div></section>','Formatea moneda con Intl.NumberFormat en el proyecto real; el ejemplo deja el dato visible para concentrarse en React.'),
    B('Formulario','Registrar mercancía desde React','El formulario conserva campos controlados en un único estado. Al enviarlo evita la recarga del navegador, convierte precio y stock al tipo esperado y llama POST /products. Mientras espera, desactiva el botón para impedir envíos dobles. Si funciona, entrega el producto creado a App; si falla, muestra el mensaje devuelto por la API.','import { useState } from "react";\nimport { request } from "../services/api";\n\nexport function ProductForm({ onCreated }) {\n  const [form, setForm] = useState({ sku: "", name: "", price: "", stock: "" });\n  const [status, setStatus] = useState({ loading: false, error: "" });\n\n  async function submit(event) {\n    event.preventDefault();\n    setStatus({ loading: true, error: "" });\n    try {\n      const product = await request("/products", {\n        method: "POST",\n        body: JSON.stringify({ ...form, stock: Number(form.stock) }),\n      });\n      onCreated(product);\n      setForm({ sku: "", name: "", price: "", stock: "" });\n      setStatus({ loading: false, error: "" });\n    } catch (error) {\n      setStatus({ loading: false, error: error.message });\n    }\n  }\n\n  return <form onSubmit={submit}>{/* inputs con label */}</form>;\n}','<form style="font-family:system-ui;max-width:420px;padding:18px;border:1px solid #cbd5e1;border-radius:14px"><h2>Nuevo producto</h2><label>Nombre<br><input value="Chocolate" style="margin:5px 0 12px;padding:8px;width:90%"></label><br><label>Stock<br><input value="10" style="margin:5px 0 12px;padding:8px;width:90%"></label><br><button style="background:#2563eb;color:white;border:0;padding:9px 15px;border-radius:8px">Guardar producto</button></form>','Completa cada input con label, name, value, onChange y restricciones HTML; FastAPI vuelve a validar porque el navegador no es una frontera confiable.'),
    B('Venta','Enviar el carrito a FastAPI','SaleForm transforma el carrito visual en el contrato que entiende POST /sales: product_id y quantity. React muestra el botón como ocupado durante la petición. FastAPI comprueba stock y guarda todo en una transacción; al recibir 201, React limpia el carrito, muestra el recibo y pide nuevamente el inventario para reflejar la cantidad confirmada por PostgreSQL.','async function confirmSale() {\n  setSaleState({ loading: true, error: "", receipt: null });\n  try {\n    const receipt = await request("/sales", {\n      method: "POST",\n      body: JSON.stringify({\n        items: cart.map(({ id, quantity }) => ({\n          product_id: id,\n          quantity,\n        })),\n      }),\n    });\n    setCart([]);\n    setSaleState({ loading: false, error: "", receipt });\n    await loadProducts();\n  } catch (error) {\n    setSaleState({ loading: false, error: error.message, receipt: null });\n  }\n}\n\n<button disabled={!cart.length || saleState.loading} onClick={confirmSale}>\n  {saleState.loading ? "Procesando..." : "Confirmar venta"}\n</button>','<aside style="font-family:system-ui;max-width:360px;padding:18px;background:#0f172a;color:white;border-radius:16px"><h2>Carrito</h2><p>Pan × 2 <span style="float:right">$4.000</span></p><p>Leche × 1 <span style="float:right">$4.700</span></p><hr><p><b>Total</b><b style="float:right">$8.700</b></p><button style="width:100%;background:#34d399;border:0;padding:10px;border-radius:9px">Confirmar venta</button></aside>','El total mostrado ayuda a Ana, pero el backend debe calcular y confirmar el total definitivo usando precios almacenados.'),
    B('Pantalla','Coordinar carga, error e inventario','App mantiene el estado compartido del caso: productos, carrito y estado de carga. useEffect solicita el inventario al montar la pantalla. La vista ofrece mensajes visibles y conserva responsabilidades pequeñas: App coordina, ProductList dibuja y request conversa con la API. Después de crear o vender, se consulta nuevamente la fuente confiable.','import { useEffect, useState } from "react";\nimport { request } from "./services/api";\nimport { ProductList } from "./components/ProductList";\n\nexport default function App() {\n  const [products, setProducts] = useState([]);\n  const [error, setError] = useState("");\n  const [loading, setLoading] = useState(true);\n\n  async function loadProducts() {\n    setLoading(true);\n    try {\n      const data = await request("/products");\n      setProducts(data.items);\n      setError("");\n    } catch (error) {\n      setError(error.message);\n    } finally {\n      setLoading(false);\n    }\n  }\n\n  useEffect(() => { loadProducts(); }, []);\n\n  return (\n    <main className="min-h-screen bg-slate-50 px-4 py-8 sm:px-8">\n      <div className="mx-auto max-w-6xl">\n        <h1 className="text-3xl font-black text-slate-950">Tienda de Ana</h1>\n        {loading && <p role="status">Cargando inventario...</p>}\n        {error && <p role="alert" className="text-red-700">{error}</p>}\n        {!loading && !error && <ProductList products={products} onAdd={() => {}} />}\n      </div>\n    </main>\n  );\n}','<main style="font-family:system-ui;padding:24px;background:#f8fafc"><h1 style="font-size:30px">Tienda de Ana</h1><p style="color:#475569">Inventario disponible y listo para vender.</p></main>','En desarrollo, React Strict Mode puede ejecutar un efecto adicional para detectar problemas; las consultas GET deben ser seguras al repetirse.'),
    B('CORS','Permitir el frontend en FastAPI','Vite y FastAPI usan puertos distintos, por lo que el navegador los considera orígenes diferentes. CORSMiddleware autoriza explícitamente el origen del frontend. Después se ejecutan ambos servidores en terminales separadas: React en 5173 y FastAPI en 8000. Permitir cualquier origen puede parecer cómodo, pero es una mala base cuando existen credenciales.','// backend/app/main.py\nfrom fastapi import FastAPI\nfrom fastapi.middleware.cors import CORSMiddleware\n\napp = FastAPI(title="Tienda de Ana API")\napp.add_middleware(\n    CORSMiddleware,\n    allow_origins=["http://localhost:5173"],\n    allow_credentials=True,\n    allow_methods=["GET", "POST", "PATCH", "DELETE"],\n    allow_headers=["Content-Type", "Authorization"],\n)\n\n# Terminal 1\nfastapi dev app/main.py\n\n# Terminal 2\ncd frontend\nnpm run dev','<pre style="padding:16px;background:#0f172a;color:#86efac">React     http://localhost:5173\nFastAPI   http://127.0.0.1:8000\nDocs      http://127.0.0.1:8000/docs</pre>','El origen debe coincidir exactamente en protocolo, host y puerto; configura los dominios reales mediante variables de entorno al desplegar.')
  ]);

  add('Backend FastAPI · Patrones de diseño','Aplica patrones solamente cuando resuelvan una repetición o separen una responsabilidad real dentro de la tienda de Ana. La ruta empieza con patrones naturales de React y continúa con patrones de backend para reglas, persistencia e integraciones.','“Un patrón es una receta con contexto, no una obligación ni una carpeta que deba existir siempre.”','Justifica qué patrón usarías para consultar inventario, calcular descuentos y registrar una venta completa.',[
    B('Inicio','Cómo reconocer un patrón útil','Un patrón de diseño nombra una solución reutilizable para un problema que aparece repetidamente. En la tienda, separar la pantalla de la regla de venta evita que un cambio de color afecte el inventario. Antes de crear clases o capas, identifica el problema, prueba una solución directa y extrae el patrón únicamente cuando haga más clara la responsabilidad.','Problema repetido\n  ↓\nResponsabilidades mezcladas\n  ↓\nElegir el patrón mínimo\n  ↓\nCódigo más fácil de cambiar y probar\n\nNo hay repetición ni variación → no añadir patrón','<div style="font-family:system-ui;padding:18px;background:#fffbeb;border:1px solid #f59e0b;border-radius:12px"><strong>Problema primero</strong><p>El nombre del patrón viene después de entender la necesidad.</p></div>','No crees Repository, Factory o Strategy solamente porque aparecen en una lista; cada pieza adicional debe eliminar duplicación o aislar un cambio probable.'),
    B('React','Componentes y composición','El patrón Component divide la interfaz en piezas con una responsabilidad visible. App coordina la página, ProductList recorre datos y ProductCard presenta un artículo. Composition conecta esas piezas mediante props y children, evitando componentes gigantes o herencias rígidas. En la tienda permite cambiar la tarjeta sin tocar el formulario de venta.','function ProductCard({ product, actions }) {\n  return (\n    <article className="rounded-xl bg-white p-4 shadow">\n      <h3 className="font-bold">{product.name}</h3>\n      <p>Stock: {product.stock}</p>\n      <div className="mt-3">{actions}</div>\n    </article>\n  );\n}\n\n<ProductCard\n  product={product}\n  actions={<button onClick={() => add(product)}>Agregar</button>}\n/>','<article style="font-family:system-ui;padding:16px;border:1px solid #cbd5e1;border-radius:14px"><h3>Pan</h3><p>Stock: 20</p><button style="background:#059669;color:white;border:0;padding:8px 14px;border-radius:8px">Agregar</button></article>','Extrae un componente cuando tenga identidad visual, comportamiento propio o reutilización; no conviertas cada etiqueta div en un archivo.'),
    B('React','Custom Hook para lógica reutilizable','Un Custom Hook extrae lógica con estado cuando dos componentes necesitan el mismo proceso. useProducts reúne carga, error y recarga del inventario; la página decide cómo mostrar esos valores. Esto se parece a entregar a varias pantallas una misma lista de instrucciones, pero cada llamada mantiene su propio estado y ciclo de vida.','import { useCallback, useEffect, useState } from "react";\nimport { request } from "../services/api";\n\nexport function useProducts() {\n  const [products, setProducts] = useState([]);\n  const [error, setError] = useState("");\n\n  const reload = useCallback(async () => {\n    try {\n      const data = await request("/products");\n      setProducts(data.items);\n      setError("");\n    } catch (error) {\n      setError(error.message);\n    }\n  }, []);\n\n  useEffect(() => { reload(); }, [reload]);\n  return { products, error, reload };\n}','<div style="font-family:system-ui;padding:16px"><strong>useProducts()</strong><p>Entrega productos, error y función para recargar.</p></div>','Si solamente un componente usa tres líneas sencillas, conserva la lógica allí; extraer antes de detectar reutilización dificulta seguir el flujo.'),
    B('React','Observer mediante estado y props','Observer describe participantes que reaccionan cuando cambia un estado. React ya proporciona ese comportamiento: al actualizar cart con setCart, CartSummary y el contador se renderizan nuevamente con las props nuevas. No hace falta construir una clase Observable manual para el estado normal de componentes; React realiza la notificación como parte de su modelo.','function StorePage() {\n  const [cart, setCart] = useState([]);\n\n  function add(product) {\n    setCart(current => [...current, { ...product, quantity: 1 }]);\n  }\n\n  return (\n    <>\n      <CartCount count={cart.length} />\n      <ProductList products={products} onAdd={add} />\n      <CartSummary items={cart} />\n    </>\n  );\n}','<div style="font-family:system-ui;display:flex;gap:12px;align-items:center"><span style="padding:8px 12px;background:#d1fae5;border-radius:999px">Carrito: 3</span><span>Resumen actualizado</span></div>','Usa un emisor de eventos externo solamente al sincronizar con un sistema ajeno a React; para datos de la misma vista prefiere estado y props.'),
    B('Arquitectura','Capas como responsabilidades','La arquitectura por capas organiza el viaje de una solicitud. El router traduce HTTP, el servicio ejecuta la regla comercial y el repositorio habla con PostgreSQL. El schema valida el contrato y el modelo representa persistencia. Como en la tienda, quien atiende el mostrador no necesita conocer cómo están ordenados todos los estantes de la bodega.','React\n  ↓ POST /sales\nRouter: HTTP y códigos de estado\n  ↓\nSchema: estructura válida\n  ↓\nService: stock, total y venta\n  ↓\nRepository: consultas SQLAlchemy\n  ↓\nPostgreSQL: restricciones y datos','<div style="font-family:system-ui;display:grid;gap:7px;text-align:center"><span style="background:#dbeafe;padding:7px">Router</span><span style="background:#dcfce7;padding:7px">Servicio</span><span style="background:#fef3c7;padding:7px">Repositorio</span><span style="background:#f3e8ff;padding:7px">PostgreSQL</span></div>','Un CRUD pequeño puede usar router y sesión directamente; extrae el servicio cuando existan reglas y el repositorio cuando debas aislar consultas repetidas.'),
    B('Backend','Service Layer para reglas de negocio','Service Layer concentra una operación completa del negocio sin depender de detalles HTTP. create_sale recibe datos ya validados, comprueba existencias, calcula el total, guarda la venta y devuelve el resultado. Así la misma regla puede invocarse desde una ruta, una prueba o un proceso administrativo sin copiarla ni fabricar solicitudes web.','# app/services/sales.py\ndef create_sale(db: Session, data: SaleCreate) -> Sale:\n    products = product_repository.get_for_sale(db, data.items)\n    ensure_stock(products, data.items)\n\n    sale = Sale(total=calculate_total(products, data.items))\n    db.add(sale)\n    discount_stock(products, data.items)\n    db.flush()\n    return sale\n\n# router\n@router.post("/sales", response_model=SaleRead, status_code=201)\ndef create(data: SaleCreate, db: DbSession):\n    return sales_service.create_sale(db, data)','<pre style="padding:16px;background:#0f172a;color:#86efac">Ruta recibe → servicio decide → base conserva</pre>','El servicio no debe devolver Response ni conocer Tailwind; lanza errores del dominio que la frontera HTTP pueda traducir.'),
    B('Backend','Repository para consultas persistentes','Repository ofrece operaciones con nombres del negocio y esconde consultas de persistencia que se repiten. get_by_sku y get_for_sale expresan intención mejor que copiar select en distintas rutas. No pretende ocultar todas las capacidades de SQLAlchemy: agrega solamente consultas reutilizadas o complejas, manteniendo Session explícita para controlar la transacción.','# app/repositories/products.py\nclass ProductRepository:\n    def get_by_sku(self, db: Session, sku: str) -> Product | None:\n        statement = select(Product).where(Product.sku == sku)\n        return db.scalar(statement)\n\n    def get_for_sale(self, db: Session, ids: list[int]) -> list[Product]:\n        statement = (\n            select(Product)\n            .where(Product.id.in_(ids))\n            .with_for_update()\n        )\n        return list(db.scalars(statement))\n\nproduct_repository = ProductRepository()','<div style="font-family:system-ui;padding:16px"><strong>Repositorio de productos</strong><p>get_by_sku · get_for_sale</p></div>','No crees una interfaz y tres implementaciones imaginarias; una clase o módulo concreto basta hasta que exista un segundo almacenamiento real.'),
    B('Backend','Dependency Injection con Depends','Dependency Injection entrega a una función los recursos que necesita en vez de construirlos dentro. FastAPI resuelve Depends y puede proporcionar una Session por solicitud. La ruta declara db: DbSession, utiliza la conexión y al terminar la dependencia la cierra. En pruebas se puede reemplazar la dependencia sin modificar el endpoint.','from collections.abc import Generator\nfrom typing import Annotated\nfrom fastapi import Depends\nfrom sqlalchemy.orm import Session\n\ndef get_db() -> Generator[Session, None, None]:\n    with SessionLocal() as session:\n        yield session\n\nDbSession = Annotated[Session, Depends(get_db)]\n\n@router.get("/products")\ndef list_products(db: DbSession):\n    return product_repository.list(db)','<pre style="padding:16px;background:#0f172a;color:#bae6fd">FastAPI → crea Session → endpoint → cierra Session</pre>','Inyecta recursos con ciclo de vida o alternativas reales, como sesión y usuario; no conviertas valores simples en dependencias sin beneficio.'),
    B('Comportamiento','Strategy para descuentos','Strategy encapsula variantes intercambiables de una misma regla. La tienda aplica precio normal, descuento de cliente frecuente o promoción de fin de semana. Un diccionario selecciona la función adecuada y evita una cadena creciente de condicionales repartida por el servicio. Todas las estrategias reciben el mismo subtotal y devuelven un total calculado con Decimal.','from decimal import Decimal\n\ndef regular(subtotal: Decimal) -> Decimal:\n    return subtotal\n\ndef loyal_customer(subtotal: Decimal) -> Decimal:\n    return subtotal * Decimal("0.90")\n\ndef weekend(subtotal: Decimal) -> Decimal:\n    return subtotal * Decimal("0.95")\n\nDISCOUNTS = {\n    "regular": regular,\n    "loyal": loyal_customer,\n    "weekend": weekend,\n}\n\ndef apply_discount(kind: str, subtotal: Decimal) -> Decimal:\n    strategy = DISCOUNTS.get(kind, regular)\n    return strategy(subtotal).quantize(Decimal("0.01"))','<table style="width:100%;font-family:system-ui"><tr><th>Cliente</th><th>Total de $10.000</th></tr><tr><td>Regular</td><td>$10.000</td></tr><tr><td>Frecuente</td><td>$9.000</td></tr><tr><td>Fin de semana</td><td>$9.500</td></tr></table>','Dos casos estables caben en un if claro; Strategy resulta útil cuando las variantes crecen, cambian independientemente o necesitan pruebas separadas.'),
    B('Integración','Adapter para un proveedor externo','Adapter traduce un formato externo al contrato interno de la tienda. Un proveedor entrega descripcion, valor y cantidad, mientras la aplicación usa name, price y stock. El adaptador realiza esa conversión en un único lugar; si el proveedor cambia sus campos, los componentes React, servicios y modelos internos permanecen iguales.','from decimal import Decimal\n\nclass SupplierAdapter:\n    def to_product(self, external: dict) -> ProductCreate:\n        return ProductCreate(\n            sku=external["codigo"],\n            name=external["descripcion"],\n            price=Decimal(str(external["valor"])),\n            stock=int(external["cantidad"]),\n        )\n\nexternal = {\n    "codigo": "PAN-01",\n    "descripcion": "Pan",\n    "valor": 2000,\n    "cantidad": 20,\n}\nproduct = SupplierAdapter().to_product(external)','<div style="font-family:system-ui;padding:16px"><code>descripcion</code> → <code>name</code><br><code>valor</code> → <code>price</code><br><code>cantidad</code> → <code>stock</code></div>','Valida la respuesta externa y registra errores sin exponer secretos; el adaptador traduce formatos, no debe decidir descuentos ni inventario.'),
    B('Creación','Factory para elegir una notificación','Factory concentra la creación cuando el tipo solicitado determina qué objeto o función utilizar. Después de vender, Ana puede enviar recibo por correo o mensaje. La fábrica valida el canal y devuelve el notificador apropiado. Si solamente existe correo, construir EmailNotifier directamente es más claro y la fábrica todavía no hace falta.','class EmailNotifier:\n    def send(self, sale: Sale) -> None:\n        print("Recibo enviado por correo", sale.id)\n\nclass SmsNotifier:\n    def send(self, sale: Sale) -> None:\n        print("Recibo enviado por SMS", sale.id)\n\ndef create_notifier(channel: str):\n    notifiers = {\n        "email": EmailNotifier,\n        "sms": SmsNotifier,\n    }\n    try:\n        return notifiers[channel]()\n    except KeyError:\n        raise ValueError("Canal de notificación no soportado")\n\nnotifier = create_notifier("email")\nnotifier.send(sale)','<div style="font-family:system-ui;padding:16px;background:#ecfdf5"><strong>Venta #15</strong><p>Recibo enviado por correo.</p></div>','No uses Factory para ocultar una llamada sencilla a una sola clase; añádela cuando la creación varíe realmente por configuración o tipo.'),
    B('Transacción','Unit of Work en una venta completa','Unit of Work agrupa cambios que deben confirmarse o cancelarse juntos. Al vender, se crea sale, se agregan detalles y se descuenta stock dentro de una transacción. El bloque with db.begin confirma al finalizar; ante una excepción realiza rollback. SQLAlchemy Session ya cumple esta responsabilidad, por lo que no es necesario envolverla en otra clase para este proyecto.','def register_sale(db: Session, data: SaleCreate) -> Sale:\n    with db.begin():\n        products = product_repository.get_for_sale(\n            db, [item.product_id for item in data.items]\n        )\n        ensure_stock(products, data.items)\n        sale = build_sale(products, data.items)\n        db.add(sale)\n        discount_stock(products, data.items)\n    return sale\n\n# Todo correcto: COMMIT\n# Cualquier error: ROLLBACK','<div style="font-family:system-ui;padding:16px;text-align:center"><strong>Venta + detalles + stock</strong><p style="color:#047857">Todo se guarda</p><p>o</p><p style="color:#b91c1c">nada cambia</p></div>','Evita commit dentro de cada repositorio: la operación de negocio debe controlar una única frontera transaccional.'),
    B('Mapa final','Cómo se combinan sin confundirse','La pantalla compone ProductCard y CartSummary; useProducts reutiliza lógica de consulta; el estado actualiza observadores de React. FastAPI inyecta Session en el router, el servicio coordina la venta, Repository obtiene productos, Strategy calcula el descuento, Adapter traduce proveedores, Factory elige la notificación y la transacción confirma el conjunto. Cada patrón conserva un motivo comprobable.','React\n├─ Component: ProductCard\n├─ Custom Hook: useProducts\n└─ Observer: estado → interfaz\n\nFastAPI\n├─ Layers: router → service → repository\n├─ Dependency Injection: DbSession\n├─ Strategy: descuentos\n├─ Adapter: proveedor externo\n├─ Factory: notificaciones\n└─ Unit of Work: transacción de venta','<section style="font-family:system-ui;padding:18px;background:#f8fafc;border:1px solid #cbd5e1;border-radius:14px"><h2>Venta organizada</h2><p>La interfaz solicita, el servicio decide y una transacción conserva el resultado.</p></section>','Como práctica, elimina mentalmente cada patrón: si el caso sigue igual de claro y seguro con menos piezas, utiliza la solución más sencilla.')
  ]);

  add('Backend FastAPI · Armar el proyecto','Construye manualmente la estructura del backend de la tienda de Ana desde el Explorador de VS Code. Cada paso indica sobre qué carpeta hacer clic, qué elemento crear y cómo debe verse el árbol antes de continuar, sin utilizar comandos para fabricar carpetas.','“Primero crea un lugar claro para cada responsabilidad; después escribe el código que corresponde a ese lugar.”','Reproduce los nueve pasos y compara tu Explorador con el árbol final del backend.',[
    B('Inicio','1. Crear y abrir la carpeta principal','En el Explorador de archivos de Windows crea una carpeta llamada tienda-ana y dentro de ella otra llamada backend. Abre VS Code, selecciona Archivo → Abrir carpeta y elige backend. En el panel Explorador debe aparecer backend como raíz; todo lo que sigue se construirá dentro de ella, nunca al lado ni encima.','1. Abrir el Explorador de archivos de Windows\n2. Entrar en Documentos o en la ubicación elegida\n3. Clic derecho → Nuevo → Carpeta\n4. Escribir tienda-ana y abrirla\n5. Crear dentro la carpeta backend\n6. VS Code → Archivo → Abrir carpeta\n7. Elegir tienda-ana/backend\n\nResultado actual:\nbackend/','<pre style="padding:16px;background:#0f172a;color:#bae6fd">VS Code · EXPLORADOR\n▼ BACKEND\n  La carpeta está vacía</pre>','Confirma que BACKEND sea el título raíz del Explorador antes de crear app; esto evita construir el proyecto en otra ubicación.'),
    B('Paquete','2. Crear app y el punto de entrada','Coloca el cursor sobre BACKEND, utiliza el icono Nueva carpeta y escribe app. Después selecciona app, pulsa Nuevo archivo y crea __init__.py; repite para main.py. __init__.py identifica el paquete Python y main.py contendrá la instancia de FastAPI. Observa la sangría para comprobar que ambos archivos quedaron dentro de app.','1. Seleccionar BACKEND\n2. Nueva carpeta → app\n3. Seleccionar app\n4. Nuevo archivo → __init__.py\n5. Nuevo archivo → main.py\n\nResultado actual:\nbackend/\n└─ app/\n   ├─ __init__.py\n   └─ main.py','<pre style="padding:16px;background:#0f172a;color:#bae6fd">▼ BACKEND\n  ▼ app\n      __init__.py\n      main.py</pre>','Los dos archivos deben aparecer con la misma sangría debajo de app; main.py no debe quedar directamente en backend.'),
    B('Configurar','3. Crear core para configuración y seguridad','Haz clic derecho sobre app y crea core. Dentro de core crea __init__.py, config.py y security.py. config.py leerá DATABASE_URL y otras variables del entorno; security.py se reserva para autenticación cuando se implemente. La configuración queda separada de las rutas para que ninguna pantalla ni endpoint contenga contraseñas.','1. Clic derecho sobre app\n2. Nueva carpeta → core\n3. Clic derecho sobre core\n4. Nuevo archivo → __init__.py\n5. Nuevo archivo → config.py\n6. Nuevo archivo → security.py\n\nResultado añadido:\napp/\n└─ core/\n   ├─ __init__.py\n   ├─ config.py\n   └─ security.py','<pre style="padding:16px;background:#0f172a;color:#c4b5fd">app/\n└─ core/\n   ├─ config.py\n   └─ security.py</pre>','security.py puede permanecer vacío al comenzar; no agregues autenticación hasta que la conexión y el CRUD básico funcionen.'),
    B('Base de datos','4. Crear db para la conexión','Vuelve a seleccionar app y crea la carpeta db al mismo nivel que core. Dentro agrega __init__.py, base.py y session.py. base.py declara la base común de los modelos; session.py crea engine y SessionLocal usando la configuración. Esta separación permite localizar la conexión sin mezclarla con productos o ventas.','1. Seleccionar app, no core\n2. Nueva carpeta → db\n3. Seleccionar db\n4. Nuevo archivo → __init__.py\n5. Nuevo archivo → base.py\n6. Nuevo archivo → session.py\n\nResultado añadido:\napp/\n├─ core/\n└─ db/\n   ├─ __init__.py\n   ├─ base.py\n   └─ session.py','<pre style="padding:16px;background:#0f172a;color:#86efac">app/\n├─ core/\n└─ db/\n   ├─ base.py\n   └─ session.py</pre>','core y db deben verse alineadas; si db aparece dentro de core, arrástrala sobre app antes de continuar.'),
    B('Datos','5. Crear models y schemas','Dentro de app crea dos carpetas hermanas: models y schemas. models representa tablas de PostgreSQL y contiene product.py y sale.py. schemas define los datos permitidos al entrar y salir de FastAPI y contiene los mismos dominios sin guardar la sesión. Cada carpeta recibe __init__.py para mantener importaciones claras.','1. Clic derecho sobre app → Nueva carpeta → models\n2. Dentro de models crear __init__.py\n3. Crear product.py y sale.py\n4. Clic derecho sobre app → Nueva carpeta → schemas\n5. Dentro de schemas crear __init__.py\n6. Crear product.py y sale.py\n\nResultado añadido:\napp/\n├─ models/\n│  ├─ product.py\n│  └─ sale.py\n└─ schemas/\n   ├─ product.py\n   └─ sale.py','<pre style="padding:16px;background:#0f172a;color:#fef08a">models/product.py → tabla\nschemas/product.py → contrato JSON</pre>','Que dos archivos se llamen product.py es correcto porque viven en carpetas distintas y cumplen responsabilidades diferentes.'),
    B('Negocio','6. Crear repositories y services','Selecciona app y crea repositories para las consultas reutilizables de SQLAlchemy; agrega products.py y sales.py. Después crea services al mismo nivel con los mismos archivos para las reglas de inventario y venta. El repositorio pregunta o persiste datos; el servicio decide si existe stock, calcula el total y coordina la transacción.','1. Sobre app crear repositories\n2. Dentro crear __init__.py\n3. Crear products.py y sales.py\n4. Sobre app crear services\n5. Dentro crear __init__.py\n6. Crear products.py y sales.py\n\nResultado añadido:\napp/\n├─ repositories/\n│  ├─ products.py\n│  └─ sales.py\n└─ services/\n   ├─ products.py\n   └─ sales.py','<pre style="padding:16px;background:#0f172a;color:#fed7aa">repositories → consulta\nservices → regla de negocio</pre>','Si el primer CRUD todavía es muy pequeño, escribe una operación simple antes de llenar todas las capas; las carpetas muestran el destino, no obligan a inventar código.'),
    B('HTTP','7. Crear api y sus rutas','Dentro de app crea api y dentro de ella routes. Agrega __init__.py en ambas carpetas. En routes crea products.py, sales.py y health.py. Esos archivos reciben solicitudes HTTP, validan mediante schemas, llaman services y devuelven códigos y respuestas. main.py incluirá los routers, pero no debe copiar su lógica.','1. Clic derecho sobre app → Nueva carpeta → api\n2. Dentro de api crear __init__.py\n3. Clic derecho sobre api → Nueva carpeta → routes\n4. Dentro de routes crear __init__.py\n5. Crear products.py\n6. Crear sales.py\n7. Crear health.py\n\nResultado añadido:\napp/\n└─ api/\n   ├─ __init__.py\n   └─ routes/\n      ├─ __init__.py\n      ├─ products.py\n      ├─ sales.py\n      └─ health.py','<pre style="padding:16px;background:#0f172a;color:#93c5fd">api/routes/\n├─ products.py\n├─ sales.py\n└─ health.py</pre>','routes debe estar dentro de api; utiliza la sangría del Explorador para confirmar la relación antes de crear sus archivos.'),
    B('Calidad','8. Crear tests, migrations y archivos raíz','Regresa a BACKEND y crea tests al mismo nivel que app; agrega test_health.py y test_products.py. Crea migrations y dentro versions para el historial de PostgreSQL. Finalmente crea en BACKEND los archivos .env.example, .gitignore, requirements.txt y README.md. Estos archivos pertenecen a la raíz porque configuran el proyecto completo.','1. Seleccionar BACKEND → Nueva carpeta → tests\n2. Crear tests/test_health.py\n3. Crear tests/test_products.py\n4. Seleccionar BACKEND → Nueva carpeta → migrations\n5. Dentro crear versions\n6. Seleccionar BACKEND y crear:\n   .env.example\n   .gitignore\n   requirements.txt\n   README.md\n\napp, tests y migrations deben quedar alineadas.','<pre style="padding:16px;background:#0f172a;color:#fca5a5">backend/\n├─ app/\n├─ tests/\n├─ migrations/\n├─ .env.example\n├─ .gitignore\n├─ requirements.txt\n└─ README.md</pre>','No crees .env con una contraseña real hasta haber confirmado que .gitignore contiene esa entrada.'),
    B('Resultado','9. Comparar el árbol completo','Despliega todas las carpetas en el Explorador y compara nivel por nivel. app contiene el código; api recibe HTTP; core configura; db conecta; models representa tablas; schemas define JSON; repositories consulta; services aplica reglas; tests verifica y migrations conserva la evolución del esquema. Si un elemento tiene otra sangría, muévelo antes de escribir código.','backend/\n├─ app/\n│  ├─ api/routes/\n│  │  ├─ health.py\n│  │  ├─ products.py\n│  │  └─ sales.py\n│  ├─ core/\n│  │  ├─ config.py\n│  │  └─ security.py\n│  ├─ db/\n│  │  ├─ base.py\n│  │  └─ session.py\n│  ├─ models/\n│  ├─ schemas/\n│  ├─ repositories/\n│  ├─ services/\n│  ├─ __init__.py\n│  └─ main.py\n├─ migrations/versions/\n├─ tests/\n├─ .env.example\n├─ .gitignore\n├─ requirements.txt\n└─ README.md','<pre style="padding:16px;background:#0f172a;color:#86efac">Estructura completa ✓\nSiguiente: configurar entorno y primer endpoint</pre>','Continúa con Preparación y escribe el proyecto en orden: config, db, modelo, schema, migración, servicio, ruta y prueba.')
  ]);

  add('Backend FastAPI · Preparación','Prepara Python, PostgreSQL, dependencias, variables de entorno y una estructura de carpetas mantenible desde el primer endpoint.','“Un entorno reproducible evita que el proyecto funcione solamente en una computadora.”','Crea el proyecto vacío y ejecuta una comprobación de salud.',[
    B('Requisitos','Herramientas necesarias','Necesitas Python moderno, PostgreSQL, un editor, terminal y Git. Comprueba que python y psql sean reconocidos antes de instalar paquetes. En Windows, py puede reemplazar a python. No trabajes con el usuario administrador de PostgreSQL desde la aplicación.','python --version\npsql --version\ngit --version','<pre style="padding:16px;background:#0f172a;color:#a7f3d0">Python ✓\nPostgreSQL ✓\nGit ✓</pre>','Consulta la compatibilidad de cada dependencia antes de actualizar versiones mayores.'),
    B('Entorno','Crear y activar el entorno virtual','venv aísla las dependencias de este backend. En PowerShell se activa con el script dentro de .venv; después python y pip apuntan al entorno. La carpeta .venv se excluye de Git porque puede reconstruirse desde el archivo de dependencias.','mkdir backend-fastapi\ncd backend-fastapi\npython -m venv .venv\n.\\.venv\\Scripts\\Activate.ps1\npython -m pip install --upgrade pip\n\n# macOS o Linux: source .venv/bin/activate','<pre style="padding:16px;background:#0f172a;color:#86efac">(.venv) entorno activo</pre>','Si PowerShell bloquea el script, revisa la política de ejecución de tu equipo en vez de desactivar seguridad globalmente.'),
    B('Dependencias','Instalar paquetes iniciales','fastapi standard incluye servidor y herramientas habituales. SQLAlchemy implementa el ORM, psycopg binary conecta PostgreSQL, Alembic gestiona migraciones y pydantic-settings lee configuración. pytest y httpx permiten probar la API. Registra versiones reproducibles mediante pyproject o requirements.','python -m pip install "fastapi[standard]" sqlalchemy "psycopg[binary]" alembic pydantic-settings pytest httpx\npython -m pip freeze > requirements.txt','<pre style="padding:16px;background:#0f172a;color:#86efac">FastAPI · SQLAlchemy · Psycopg · Alembic instalados</pre>','No guardes .venv en Git; sí guarda el archivo que declara dependencias.'),
    B('Git','Archivos que no deben subirse','.gitignore excluye entorno virtual, cachés, archivos locales, cobertura y secretos. .env.example documenta variables usando valores falsos; .env contiene credenciales reales y nunca se confirma. README explica instalación, migraciones y ejecución.','# .gitignore\n.venv/\n__pycache__/\n.pytest_cache/\n.coverage\n.env\n\n# .env.example\nDATABASE_URL=postgresql+psycopg://app_user:CHANGE_ME@localhost:5432/app_db\nSECRET_KEY=CHANGE_ME','<pre style="padding:16px;background:#0f172a;color:#fbbf24">.env ignorado · .env.example versionado</pre>','Comprueba git status antes de cada commit para evitar publicar credenciales.'),
    B('Carpetas','Estructura inicial del backend','app contiene el código importable. api reúne routers, core configuración y seguridad, db conexión y modelos, schemas contratos, services reglas y main crea FastAPI. tests refleja comportamientos importantes. Alembic conserva el historial del esquema y no debe confundirse con datos de prueba.','backend-fastapi/\n├─ app/\n│  ├─ api/routes/\n│  ├─ core/\n│  ├─ db/\n│  ├─ models/\n│  ├─ schemas/\n│  ├─ services/\n│  └─ main.py\n├─ migrations/versions/\n├─ tests/\n├─ .env.example\n├─ .gitignore\n├─ alembic.ini\n├─ pyproject.toml\n└─ README.md','<pre style="padding:16px;background:#0f172a;color:#bae6fd">app/api · core · db · models · schemas · services\ntests · migrations</pre>','Añade __init__.py donde corresponda al paquete Python; evita una carpeta utils con responsabilidades mezcladas.'),
    B('Configuración','Leer variables de entorno','BaseSettings convierte variables de entorno en valores tipados. lru_cache evita reconstruir la configuración en cada solicitud. La URL utiliza el dialecto postgresql y el driver psycopg. Los secretos se inyectan desde el entorno local o el administrador de secretos del despliegue.','from functools import lru_cache\nfrom pydantic_settings import BaseSettings, SettingsConfigDict\n\nclass Settings(BaseSettings):\n    database_url: str\n    secret_key: str\n    model_config = SettingsConfigDict(env_file=".env", extra="ignore")\n\n@lru_cache\ndef get_settings() -> Settings:\n    return Settings()','<pre style="padding:16px;background:#0f172a;color:#a7f3d0">Configuración validada ✓</pre>','No asignes una contraseña real como valor predeterminado dentro del código.'),
    B('Inicio','Primer archivo main.py','La instancia FastAPI contiene metadatos visibles en OpenAPI. El endpoint health permite confirmar que el proceso responde sin probar todavía la base de datos. fastapi dev inicia el servidor con recarga para desarrollo y expone documentación interactiva en /docs.','from fastapi import FastAPI\n\napp = FastAPI(title="Products API", version="1.0.0")\n\n@app.get("/health", tags=["health"])\ndef health() -> dict[str, str]:\n    return {"status": "ok"}\n\n# Terminal\nfastapi dev app/main.py',response('GET','/health','200','{\n  "status": "ok"\n}'),'Usa el servidor de desarrollo solamente en tu equipo; producción requiere otra configuración.')
  ]);

  add('Backend FastAPI · API','Construye contratos con Pydantic, parámetros, errores, routers, dependencias y documentación automática antes de conectar la base de datos.','“Un endpoint claro valida entradas y limita exactamente lo que devuelve.”','Crea una API temporal de productos y comprueba su contrato en /docs.',[
    B('Rutas','Operaciones de ruta','El decorador relaciona método y URL con una función. Los parámetros anotados se validan y documentan. Una respuesta debe tener estructura estable y un código coherente. FastAPI convierte diccionarios y modelos a JSON, pero la lógica de negocio no debería quedar encerrada en el decorador.','from fastapi import FastAPI, status\n\napp = FastAPI()\n\n@app.post("/products", status_code=status.HTTP_201_CREATED)\ndef create_product():\n    return {"id": 1, "name": "Keyboard", "price": "49.90"}',response('POST','/products','201','{\n  "id": 1,\n  "name": "Keyboard",\n  "price": "49.90"\n}'),'Usa nombres plurales y consistentes para recursos.'),
    B('Schemas','Validar cuerpos con Pydantic','BaseModel declara campos, tipos y restricciones. El schema de creación acepta solamente datos editables; el identificador se genera en el servidor. Decimal evita errores binarios para dinero y Field expresa límites. Un cuerpo inválido obtiene 422 con detalles utilizables por el cliente.','from decimal import Decimal\nfrom pydantic import BaseModel, Field\n\nclass ProductCreate(BaseModel):\n    name: str = Field(min_length=2, max_length=120)\n    price: Decimal = Field(gt=0, max_digits=10, decimal_places=2)\n    stock: int = Field(ge=0)\n\n@app.post("/products", status_code=201)\ndef create_product(data: ProductCreate):\n    return data',response('POST','/products','422','{\n  "detail": [{"loc": ["body", "price"], "msg": "Input should be greater than 0"}]\n}'),'La validación de formato no sustituye reglas como nombre único o stock disponible.'),
    B('Parámetros','Path y query parameters','Un parámetro presente en la ruta se interpreta como path; los demás valores simples se leen normalmente desde query. Query agrega límites y descripción. La paginación limita consumo de memoria y evita devolver tablas completas. Los tipos convierten y rechazan valores incorrectos automáticamente.','from typing import Annotated\nfrom fastapi import Query\n\n@app.get("/products/{product_id}")\ndef get_product(product_id: int):\n    return {"id": product_id}\n\n@app.get("/products")\ndef list_products(\n    q: str | None = None,\n    limit: Annotated[int, Query(ge=1, le=100)] = 20,\n    offset: Annotated[int, Query(ge=0)] = 0,\n):\n    return {"q": q, "limit": limit, "offset": offset}',response('GET','/products?q=key&limit=20','200','{ "q": "key", "limit": 20, "offset": 0 }'),'Define un máximo de página y un orden estable antes de paginar datos reales.'),
    B('Salida','Response models','Un schema de salida documenta la respuesta y filtra campos que no deben salir, como hashes o datos internos. ConfigDict from_attributes permite construirlo desde objetos ORM. Separa ProductCreate, ProductUpdate y ProductRead porque cada operación tiene campos opcionales y permisos diferentes.','from pydantic import BaseModel, ConfigDict\n\nclass ProductRead(BaseModel):\n    id: int\n    name: str\n    price: Decimal\n    stock: int\n    model_config = ConfigDict(from_attributes=True)\n\n@app.get("/products/{product_id}", response_model=ProductRead)\ndef get_product(product_id: int): ...','<pre style="padding:16px;background:#fff;color:#334155">ProductRead: id · name · price · stock\nSin campos privados</pre>','Nunca devuelvas directamente un modelo de usuario que contenga password_hash.'),
    B('Errores','HTTPException y errores de dominio','HTTPException detiene la operación con estado y detalle. 404 indica recurso inexistente; 409 representa un conflicto como nombre duplicado; 400 sirve para una solicitud inválida que no encaja mejor. Los servicios pueden lanzar errores de dominio y el router traducirlos a HTTP de forma consistente.','from fastapi import HTTPException, status\n\ndef require_product(product):\n    if product is None:\n        raise HTTPException(\n            status_code=status.HTTP_404_NOT_FOUND,\n            detail="Product not found",\n        )\n    return product',response('GET','/products/999','404','{\n  "detail": "Product not found"\n}'),'No devuelvas 200 con un campo error; utiliza el estado HTTP apropiado.'),
    B('Routers','Separar rutas por recurso','APIRouter agrupa prefijo, etiquetas, dependencias y operaciones relacionadas. main incluye el router bajo /api/v1, dejando explícita la versión pública. Esta separación mantiene pequeño el punto de entrada y permite probar o sustituir grupos completos.','# app/api/routes/products.py\nrouter = APIRouter(prefix="/products", tags=["products"])\n\n@router.get("")\ndef list_products(): ...\n\n# app/main.py\nfrom app.api.routes import products\napp.include_router(products.router, prefix="/api/v1")','<pre style="padding:16px;background:#0f172a;color:#bae6fd">/api/v1/products\n/api/v1/products/{id}</pre>','Versiona el contrato público cuando un cambio incompatible lo requiera, no cada modificación interna.'),
    B('Dependencias','Depends y recursos compartidos','Una dependencia declara algo que el endpoint necesita: configuración, sesión, autenticación o paginación. FastAPI resuelve el árbol y ejecuta la limpieza de dependencias con yield. Annotated conserva el tipo para editor y análisis estático sin repetir Depends en cada firma.','from typing import Annotated\nfrom fastapi import Depends\n\ndef pagination(limit: int = 20, offset: int = 0):\n    return {"limit": min(max(limit, 1), 100), "offset": max(offset, 0)}\n\nPage = Annotated[dict, Depends(pagination)]\n\n@router.get("")\ndef list_products(page: Page):\n    return page','<pre style="padding:16px;background:#fff;color:#334155">Dependencia Page → limit 20 · offset 0</pre>','Usa dependencias para políticas y recursos compartidos, no para ocultar toda la lógica del endpoint.')
  ]);

  add('Backend FastAPI · Instalar PostgreSQL','Instala PostgreSQL en Windows, comprueba el servidor, crea una base y un usuario exclusivos para la tienda de Ana y conecta FastAPI mediante SQLAlchemy y Psycopg. Cada paso incluye una señal concreta para saber si quedó funcionando.','“Primero confirma PostgreSQL solo; después conecta Python; por último prueba la API. Así sabes en qué tramo buscar un error.”','Instala el servidor, crea tienda_db y consigue que GET /health/ready responda database: ready.',[
    B('Descarga','Obtener el instalador para Windows','Descarga el instalador desde la página oficial de PostgreSQL para Windows, que enlaza el instalador certificado de EDB. Elige una versión estable compatible con tu sistema de 64 bits. Evita instaladores publicados en páginas desconocidas. El paquete incluye el servidor, pgAdmin y herramientas de línea de comandos como psql.','1. Visita postgresql.org/download/windows/\n2. Abre “Download the installer”\n3. Elige Windows x86-64\n4. Descarga una versión estable soportada\n5. Ejecuta el instalador como administrador si Windows lo solicita','<section style="font-family:system-ui;padding:18px;background:#eff6ff;border:1px solid #93c5fd;border-radius:14px"><h2>Instalador de PostgreSQL</h2><p>Servidor · pgAdmin · herramientas de línea de comandos</p></section>','Conserva la versión elegida en las notas del proyecto; no necesitas StackBuilder para este ejemplo básico.'),
    B('Asistente','Configurar el instalador paso a paso','Mantén seleccionados PostgreSQL Server, pgAdmin y Command Line Tools. Conserva el directorio de datos sugerido, crea una contraseña segura para el superusuario postgres, usa el puerto 5432 si está libre y deja la configuración regional apropiada. Esa contraseña administra el servidor, pero no será la credencial diaria de FastAPI.','Componentes:\n[x] PostgreSQL Server\n[x] pgAdmin 4\n[x] Command Line Tools\n[ ] StackBuilder (opcional)\n\nDatos de instalación:\nPuerto: 5432\nUsuario administrador: postgres\nContraseña: definida por ti\nLocale: predeterminado del sistema','<div style="font-family:system-ui;padding:18px"><strong>Configuración local</strong><p>localhost : 5432 · usuario administrador postgres</p></div>','Guarda la contraseña del administrador en un gestor seguro; si 5432 está ocupado, elige otro puerto y úsalo también en todas las conexiones.'),
    B('Servicio','Comprobar servidor y comando psql','Al terminar, PostgreSQL debe aparecer como un servicio de Windows en ejecución. PowerShell puede localizarlo con Get-Service. psql --version confirma que las herramientas están en PATH; si el comando no existe, abre SQL Shell desde Inicio o agrega la carpeta bin de la versión instalada al PATH y abre una terminal nueva.','Get-Service -Name "postgresql*"\npsql --version\n\n# Resultado esperado\nStatus   Name\nRunning  postgresql-x64-<version>\n\n# Carpeta habitual de las herramientas\nC:\\Program Files\\PostgreSQL\\<version>\\bin','<pre style="padding:16px;background:#0f172a;color:#86efac">Servicio: Running\npsql: versión instalada ✓</pre>','No reinstales el servidor solamente porque psql no está en PATH: primero prueba SQL Shell o la ruta bin instalada.'),
    B('Acceso','Primera conexión con psql o pgAdmin','Conéctate primero a la base administrativa postgres usando el usuario postgres y la contraseña creada en el instalador. En psql, host, puerto, usuario y base se indican explícitamente. En pgAdmin registra un servidor con los mismos datos. SELECT version confirma que el cliente pudo comunicarse y autenticarse con el servidor.','# PowerShell o SQL Shell\npsql -h localhost -p 5432 -U postgres -d postgres\n\n# Dentro de psql\nSELECT version();\n\\l\n\\q\n\n# pgAdmin\nHost: localhost\nPort: 5432\nMaintenance database: postgres\nUsername: postgres','<pre style="padding:16px;background:#0f172a;color:#bae6fd">postgres=# SELECT version();\nPostgreSQL ...\npostgres=#</pre>','Que pgAdmin abra no demuestra que el servidor esté conectado; ejecuta una consulta y verifica el resultado.'),
    B('Base','Crear usuario y base para la tienda','El usuario postgres se reserva para administración. Crea tienda_user con LOGIN y una contraseña distinta, y asigna a ese usuario la propiedad de tienda_db. Al conectarte de nuevo como tienda_user compruebas que la aplicación tendrá acceso sin usar privilegios globales. Los nombres en minúsculas evitan tener que escribir comillas en cada consulta.','-- Ejecutar conectado como postgres\nCREATE ROLE tienda_user WITH LOGIN PASSWORD \'CAMBIA_ESTA_CLAVE\';\nCREATE DATABASE tienda_db OWNER tienda_user;\n\n-- Salir y comprobar con el nuevo usuario\n\\q\npsql -h localhost -p 5432 -U tienda_user -d tienda_db\n\n-- Dentro de tienda_db\nSELECT current_user, current_database();','<pre style="padding:16px;background:#0f172a;color:#86efac">current_user: tienda_user\ncurrent_database: tienda_db</pre>','Cambia la clave de ejemplo. Si la base ya existe, no repitas CREATE: inspecciona primero con \\du y \\l.'),
    B('Python','Instalar el driver y la configuración','Activa el entorno virtual del backend e instala SQLAlchemy, Psycopg y pydantic-settings. Psycopg es el conductor que lleva operaciones Python hasta PostgreSQL; SQLAlchemy administra conexiones y consultas; pydantic-settings lee la URL desde .env. La variante binary simplifica el entorno local de aprendizaje en Windows.','cd backend\n.\\.venv\\Scripts\\Activate.ps1\npython -m pip install sqlalchemy "psycopg[binary]" pydantic-settings\n\n# Comprobar imports\npython -c "import sqlalchemy, psycopg; print(sqlalchemy.__version__, psycopg.__version__)"','<pre style="padding:16px;background:#0f172a;color:#86efac">SQLAlchemy ✓  Psycopg ✓</pre>','En despliegue revisa la opción de instalación de Psycopg adecuada para la plataforma; registra las dependencias del proyecto para reproducir el entorno.'),
    B('Entorno','Construir DATABASE_URL sin publicar secretos','FastAPI necesita host, puerto, usuario, contraseña y nombre de base. SQLAlchemy selecciona Psycopg mediante postgresql+psycopg. Guarda el valor real en .env ignorado por Git y publica solamente .env.example con una clave falsa. Si la contraseña contiene caracteres reservados de una URL, codifícalos o construye la URL con URL.create.','# backend/.env — no subir a Git\nDATABASE_URL=postgresql+psycopg://tienda_user:CAMBIA_ESTA_CLAVE@localhost:5432/tienda_db\n\n# backend/.env.example — sí subir\nDATABASE_URL=postgresql+psycopg://tienda_user:CHANGE_ME@localhost:5432/tienda_db\n\n# .gitignore\n.env','<pre style="padding:16px;background:#0f172a;color:#fbbf24">.env privado\n.env.example documenta la variable</pre>','Comprueba git status antes de confirmar cambios; una cadena de conexión contiene credenciales aunque funcione solamente en tu equipo.'),
    B('FastAPI','Crear engine y sesiones','Settings exige DATABASE_URL al iniciar. create_engine crea el administrador de conexiones una sola vez y pool_pre_ping descarta conexiones cerradas antes de prestarlas. SessionLocal fabrica una sesión independiente por solicitud. La dependencia get_db utiliza with para cerrar la sesión incluso cuando el endpoint produce un error.','# app/core/config.py\nfrom functools import lru_cache\nfrom pydantic_settings import BaseSettings, SettingsConfigDict\n\nclass Settings(BaseSettings):\n    database_url: str\n    model_config = SettingsConfigDict(env_file=".env")\n\n@lru_cache\ndef get_settings():\n    return Settings()\n\n# app/db/session.py\nfrom sqlalchemy import create_engine\nfrom sqlalchemy.orm import Session, sessionmaker\nfrom app.core.config import get_settings\n\nengine = create_engine(get_settings().database_url, pool_pre_ping=True)\nSessionLocal = sessionmaker(bind=engine, expire_on_commit=False)\n\ndef get_db():\n    with SessionLocal() as session:\n        yield session','<div style="font-family:system-ui;padding:16px"><strong>DATABASE_URL</strong> → engine → SessionLocal → endpoint</div>','Crea engine una vez, pero nunca compartas una misma Session global entre solicitudes.'),
    B('Prueba','Verificar PostgreSQL desde FastAPI','Una prueba de disponibilidad ejecuta SELECT 1 mediante SQLAlchemy. Si PostgreSQL responde, el endpoint devuelve ready; si falla, responde 503 sin revelar la contraseña ni el error interno. Esto diferencia que FastAPI esté encendido de que realmente pueda atender operaciones dependientes de la base de datos.','from fastapi import APIRouter, HTTPException\nfrom sqlalchemy import text\nfrom sqlalchemy.exc import SQLAlchemyError\nfrom app.db.session import engine\n\nrouter = APIRouter(prefix="/health", tags=["health"])\n\n@router.get("/ready")\ndef readiness():\n    try:\n        with engine.connect() as connection:\n            connection.execute(text("SELECT 1"))\n        return {"database": "ready"}\n    except SQLAlchemyError:\n        raise HTTPException(status_code=503, detail="Database unavailable")\n\n# Probar\nfastapi dev app/main.py\ncurl http://127.0.0.1:8000/health/ready',response('GET','/health/ready','200','{\n  "database": "ready"\n}'),'Registra el detalle técnico de la excepción en el servidor, pero entrega al cliente un mensaje estable que no exponga la conexión.'),
    B('Errores','Diagnóstico rápido de conexión','Resuelve los fallos por etapas. Connection refused suele indicar servicio detenido, host o puerto incorrecto. Password authentication failed señala usuario o contraseña. Database does not exist indica un nombre equivocado o una creación pendiente. ModuleNotFoundError psycopg significa que el entorno virtual activo no contiene el driver.','connection refused\n→ Get-Service postgresql*\n→ comprobar localhost y puerto\n\npassword authentication failed\n→ probar psql con el mismo usuario\n→ revisar contraseña y .env\n\ndatabase "tienda_db" does not exist\n→ psql -U postgres -d postgres -c "\\l"\n\nModuleNotFoundError: psycopg\n→ activar .venv e instalar psycopg[binary]','<table style="width:100%;font-family:system-ui"><tr><th>Error</th><th>Revisar</th></tr><tr><td>Connection refused</td><td>Servicio y puerto</td></tr><tr><td>Password failed</td><td>Usuario y clave</td></tr><tr><td>Database missing</td><td>Nombre de base</td></tr></table>','No modifiques pg_hba.conf ni desactives autenticación como primer intento; confirma antes servicio, parámetros y credenciales.')
  ]);

  add('Backend FastAPI · PostgreSQL','Configura PostgreSQL, SQLAlchemy 2, sesiones, modelos, relaciones, restricciones, índices y migraciones reproducibles.','“El esquema protege reglas incluso cuando los datos no llegan desde la API.”','Crea la tabla products mediante una migración y comprueba la conexión.',[
    B('Servidor','Crear usuario y base de datos','Conéctate como administrador solamente para aprovisionar un rol y una base. La aplicación usa su propio usuario con contraseña y permisos limitados. Los nombres se escriben en minúsculas y la contraseña real se guarda fuera del repositorio.','-- Ejecutar en psql con un usuario administrador\nCREATE ROLE app_user WITH LOGIN PASSWORD \'change-this-password\';\nCREATE DATABASE app_db OWNER app_user;\n\n-- Comprobar acceso\npsql -h localhost -U app_user -d app_db','<pre style="padding:16px;background:#0f172a;color:#86efac">app_user conectado a app_db ✓</pre>','Cambia la contraseña de ejemplo y aplica el mínimo privilegio en cada entorno.'),
    B('Conexión','Engine y URL de PostgreSQL','create_engine administra un pool de conexiones y se crea una sola vez en el módulo. La URL postgresql+psycopg selecciona PostgreSQL con Psycopg 3. pool_pre_ping comprueba conexiones recuperadas antes de usarlas. No imprimas la URL porque contiene credenciales.','from sqlalchemy import create_engine\nfrom app.core.config import get_settings\n\nsettings = get_settings()\nengine = create_engine(\n    settings.database_url,\n    pool_pre_ping=True,\n)\n\n# .env\nDATABASE_URL=postgresql+psycopg://app_user:password@localhost:5432/app_db','<pre style="padding:16px;background:#0f172a;color:#86efac">Engine PostgreSQL configurado ✓</pre>','Configura timeouts y tamaño del pool según la capacidad real del servidor.'),
    B('Sesiones','Una sesión por solicitud','sessionmaker fabrica sesiones ligadas al engine. La dependencia abre una sesión, la entrega al endpoint y la cierra siempre mediante finally. Session no debe compartirse globalmente entre solicitudes. La transacción se confirma en operaciones de escritura y se revierte cuando ocurre un error.','from collections.abc import Generator\nfrom sqlalchemy.orm import Session, sessionmaker\n\nSessionLocal = sessionmaker(bind=engine, expire_on_commit=False)\n\ndef get_db() -> Generator[Session, None, None]:\n    db = SessionLocal()\n    try:\n        yield db\n    finally:\n        db.close()','<pre style="padding:16px;background:#fff;color:#334155">Solicitud → Session → operación → close</pre>','No guardes una Session dentro de una variable global ni de un singleton.'),
    B('Modelo','Modelo Product con SQLAlchemy 2','DeclarativeBase define la base común. Mapped y mapped_column describen columnas con tipos Python y SQL. Numeric conserva precisión monetaria; CheckConstraint protege precio y stock; unique evita SKU duplicado. created_at se calcula en PostgreSQL para mantener una fuente consistente.','from datetime import datetime\nfrom decimal import Decimal\nfrom sqlalchemy import CheckConstraint, DateTime, Numeric, String, func\nfrom sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column\n\nclass Base(DeclarativeBase): pass\n\nclass Product(Base):\n    __tablename__ = "products"\n    __table_args__ = (\n        CheckConstraint("price > 0"),\n        CheckConstraint("stock >= 0"),\n    )\n    id: Mapped[int] = mapped_column(primary_key=True)\n    sku: Mapped[str] = mapped_column(String(40), unique=True, index=True)\n    name: Mapped[str] = mapped_column(String(120), index=True)\n    price: Mapped[Decimal] = mapped_column(Numeric(10, 2))\n    stock: Mapped[int]\n    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), server_default=func.now())','<pre style="padding:16px;background:#fff;color:#334155">products\nPK id · UNIQUE sku · name · price · stock · created_at</pre>','Define restricciones críticas también en PostgreSQL; la API no es el único posible escritor.'),
    B('Relaciones','Claves foráneas y relaciones','Una categoría puede tener muchos productos. category_id es la clave foránea real que PostgreSQL valida; relationship facilita navegar objetos en Python. Decide reglas on delete explícitamente y evita cargar colecciones completas sin necesidad. Una relación ORM no sustituye la restricción en la base.','class Category(Base):\n    __tablename__ = "categories"\n    id: Mapped[int] = mapped_column(primary_key=True)\n    name: Mapped[str] = mapped_column(String(80), unique=True)\n    products: Mapped[list["Product"]] = relationship(back_populates="category")\n\nclass Product(Base):\n    category_id: Mapped[int] = mapped_column(ForeignKey("categories.id", ondelete="RESTRICT"))\n    category: Mapped["Category"] = relationship(back_populates="products")','<pre style="padding:16px;background:#fff;color:#334155">categories 1 ─── * products</pre>','Evita cascadas de borrado hasta comprender exactamente qué información eliminarían.'),
    B('Consultas','select, filtros e índices','SQLAlchemy 2 utiliza select para construir consultas. where filtra, order_by garantiza orden estable y limit u offset implementan paginación. Un índice ayuda a consultas frecuentes, pero aumenta espacio y costo de escritura. Analiza los planes reales antes de crear índices por cada columna.','from sqlalchemy import select\n\nstatement = (\n    select(Product)\n    .where(Product.name.ilike(f"%{q}%"))\n    .order_by(Product.id)\n    .offset(offset)\n    .limit(limit)\n)\nproducts = db.scalars(statement).all()','<pre style="padding:16px;background:#fff;color:#334155">SELECT products ... WHERE name ILIKE ... ORDER BY id LIMIT 20</pre>','Escapa patrones de búsqueda cuando corresponda y pagina siempre con un orden determinista.'),
    B('Migraciones','Alembic y evolución del esquema','Alembic registra cambios del esquema como revisiones. Inicializa una vez, conecta target_metadata con Base.metadata, genera una revisión, revisa el archivo y aplica upgrade. Autogenerate ayuda, pero no comprende todas las transformaciones de datos: cada migración debe inspeccionarse y probarse.','alembic init migrations\n\n# migrations/env.py\nfrom app.models.base import Base\ntarget_metadata = Base.metadata\n\n# Terminal\nalembic revision --autogenerate -m "create products"\nalembic upgrade head\nalembic current','<pre style="padding:16px;background:#0f172a;color:#a7f3d0">create products → upgrade head ✓</pre>','Nunca ejecutes Base.metadata.create_all como reemplazo permanente de migraciones en producción.')
  ]);

  add('Backend FastAPI · CRUD','Conecta routers, schemas, servicios y sesiones para crear, listar, consultar, actualizar y eliminar productos con transacciones seguras.','“Cada escritura debe validar, persistir, confirmar y devolver un contrato explícito.”','Completa el CRUD y prueba errores, conflictos y paginación.',[
    B('Schemas','Schemas de entrada y salida','ProductCreate exige todos los datos necesarios; ProductUpdate vuelve opcionales los campos editables para PATCH; ProductRead incluye identificador y fecha. model_dump con exclude_unset permite distinguir un campo omitido de uno enviado. Los schemas no contienen la sesión ni ejecutan consultas.','class ProductCreate(BaseModel):\n    sku: str = Field(min_length=2, max_length=40)\n    name: str = Field(min_length=2, max_length=120)\n    price: Decimal = Field(gt=0)\n    stock: int = Field(ge=0)\n\nclass ProductUpdate(BaseModel):\n    name: str | None = Field(default=None, min_length=2, max_length=120)\n    price: Decimal | None = Field(default=None, gt=0)\n    stock: int | None = Field(default=None, ge=0)\n\nclass ProductRead(ProductCreate):\n    id: int\n    created_at: datetime\n    model_config = ConfigDict(from_attributes=True)','<pre style="padding:16px;background:#fff;color:#334155">Create: datos obligatorios\nUpdate: cambios opcionales\nRead: datos públicos</pre>','Decide si null es válido por separado de si un campo puede omitirse.'),
    B('Crear','POST con transacción','El servicio comprueba reglas como SKU único, construye el modelo, lo agrega y confirma la transacción. refresh recupera valores generados por PostgreSQL. IntegrityError todavía debe manejarse porque dos solicitudes concurrentes pueden pasar una comprobación previa y competir por la restricción unique.','def create_product(db: Session, data: ProductCreate) -> Product:\n    product = Product(**data.model_dump())\n    db.add(product)\n    try:\n        db.commit()\n    except IntegrityError:\n        db.rollback()\n        raise ProductConflict("SKU already exists")\n    db.refresh(product)\n    return product\n\n@router.post("", response_model=ProductRead, status_code=201)\ndef create(data: ProductCreate, db: DbSession):\n    return service.create_product(db, data)','<pre style="padding:16px;background:#fff;color:#334155">BEGIN → INSERT → COMMIT → REFRESH</pre>','La restricción unique es la protección final; la consulta previa solo mejora el mensaje.'),
    B('Listar','GET paginado y filtrado','La lista acepta búsqueda, limit y offset, ejecuta select con orden estable y devuelve elementos. Para clientes reales conviene incluir total o enlaces de paginación mediante un schema de página. Limita el máximo y evita contar toda la tabla innecesariamente en cada solicitud.','class ProductPage(BaseModel):\n    items: list[ProductRead]\n    total: int\n    limit: int\n    offset: int\n\n@router.get("", response_model=ProductPage)\ndef list_all(db: DbSession, q: str | None = None, limit: int = 20, offset: int = 0):\n    return service.list_products(db, q=q, limit=limit, offset=offset)',response('GET','/api/v1/products?limit=20','200','{\n  "items": [{"id": 1, "name": "Keyboard"}],\n  "total": 1, "limit": 20, "offset": 0\n}'),'Para conjuntos grandes considera paginación por cursor en lugar de offsets profundos.'),
    B('Consultar','GET por identificador','Session.get busca por clave primaria y aprovecha el mapa de identidad de la sesión. El servicio devuelve el modelo o None; el router convierte la ausencia en 404. La respuesta se filtra mediante ProductRead y no expone columnas internas agregadas después.','def get_product(db: Session, product_id: int) -> Product | None:\n    return db.get(Product, product_id)\n\n@router.get("/{product_id}", response_model=ProductRead)\ndef get_one(product_id: int, db: DbSession):\n    product = service.get_product(db, product_id)\n    if product is None:\n        raise HTTPException(status_code=404, detail="Product not found")\n    return product',response('GET','/api/v1/products/1','200','{\n  "id": 1, "sku": "KEY-01", "name": "Keyboard",\n  "price": "49.90", "stock": 8\n}'),'No reveles si un recurso protegido existe antes de comprobar autorización.'),
    B('Actualizar','PATCH parcial','exclude_unset obtiene solamente campos presentes en el cuerpo. setattr aplica cada cambio permitido al modelo cargado y commit persiste la transacción. Los campos que nunca deberían modificarse, como id o created_at, no aparecen en ProductUpdate. Maneja conflictos y revierte ante error.','def update_product(db: Session, product: Product, data: ProductUpdate) -> Product:\n    changes = data.model_dump(exclude_unset=True)\n    for field, value in changes.items():\n        setattr(product, field, value)\n    try:\n        db.commit()\n    except IntegrityError:\n        db.rollback()\n        raise ProductConflict()\n    db.refresh(product)\n    return product\n\n@router.patch("/{product_id}", response_model=ProductRead)\ndef update(product_id: int, data: ProductUpdate, db: DbSession): ...','<pre style="padding:16px;background:#fff;color:#334155">PATCH → campos enviados → UPDATE → COMMIT</pre>','No uses model_dump completo en PATCH porque sobrescribiría campos omitidos con valores predeterminados.'),
    B('Eliminar','DELETE y reglas de integridad','El endpoint localiza el producto, comprueba autorización o relaciones y lo elimina dentro de una transacción. 204 no contiene cuerpo. Si otras tablas dependen del registro, define si se restringe, archiva o elimina en cascada; no ocultes esa decisión dentro de un error genérico.','@router.delete("/{product_id}", status_code=204)\ndef delete(product_id: int, db: DbSession) -> None:\n    product = db.get(Product, product_id)\n    if product is None:\n        raise HTTPException(status_code=404, detail="Product not found")\n    db.delete(product)\n    db.commit()','<pre style="padding:16px;background:#fff;color:#334155">DELETE /products/1 → 204 No Content</pre>','Para datos auditables considera deleted_at en lugar de eliminación física.'),
    B('Transacciones','Commit, rollback y concurrencia','Una operación de negocio que modifica varias tablas debe compartir una transacción: todas se confirman o ninguna. rollback devuelve la sesión a un estado utilizable después de un error. Las restricciones de PostgreSQL protegen concurrencia; para inventario también puede requerirse bloqueo o una actualización condicional atómica.','try:\n    order = Order(...)\n    db.add(order)\n    product.stock -= quantity\n    if product.stock < 0:\n        raise OutOfStock()\n    db.commit()\nexcept Exception:\n    db.rollback()\n    raise','<pre style="padding:16px;background:#fff;color:#334155">BEGIN\n  INSERT order\n  UPDATE stock\nCOMMIT o ROLLBACK</pre>','Nunca confirmes la orden y el descuento de inventario en transacciones separadas.')
  ]);

  add('Backend FastAPI · Producción','Protege, prueba, integra y despliega la API con configuración por entorno, autenticación, CORS, observabilidad y migraciones controladas.','“Producción comienza donde terminan los ejemplos felices: errores, concurrencia, seguridad y recuperación.”','Entrega el backend con pruebas, migraciones y una configuración de despliegue reproducible.',[
    B('Seguridad','Contraseñas y tokens','Las contraseñas se almacenan con un algoritmo de hashing adecuado, nunca cifradas de forma reversible ni en texto plano. OAuth2PasswordBearer extrae el bearer token; el endpoint token verifica credenciales y emite un JWT de vida corta. Autenticación identifica y autorización decide permisos.','python -m pip install "pwdlib[argon2]" PyJWT\n\nfrom fastapi.security import OAuth2PasswordBearer\nfrom pwdlib import PasswordHash\n\npassword_hash = PasswordHash.recommended()\noauth2_scheme = OAuth2PasswordBearer(tokenUrl="/api/v1/auth/token")\n\ndef hash_password(password: str) -> str:\n    return password_hash.hash(password)\n\n# El token incluye sub, expiración y una firma con secreto externo.','<pre style="padding:16px;background:#0f172a;color:#fca5a5">password → hash Argon2\ncredenciales → token corto\nendpoint → usuario + permisos</pre>','Usa HTTPS, expiración corta y rotación; no guardes contraseñas ni tokens en logs.'),
    B('Autorización','Dependencias de usuario y permisos','get_current_user valida firma, expiración, sujeto y estado del usuario. Otra dependencia puede exigir un rol o permiso. Colocarla en el router protege todas sus operaciones, pero el servicio también debe preservar invariantes importantes. Un token válido no implica acceso a cualquier registro.','CurrentUser = Annotated[User, Depends(get_current_user)]\n\n@router.post("", dependencies=[Depends(require_admin)])\ndef create_product(data: ProductCreate, db: DbSession): ...\n\n@router.get("/{product_id}")\ndef get_product(product_id: int, user: CurrentUser, db: DbSession):\n    return service.get_authorized(db, product_id, user)','<pre style="padding:16px;background:#fff;color:#334155">401: no autenticado\n403: autenticado sin permiso\n404: recurso no visible</pre>','Valida propiedad o ámbito del recurso, no solamente el nombre del rol.'),
    B('CORS','Conectar el frontend','CORS controla qué orígenes del navegador pueden llamar la API. Declara URLs exactas para desarrollo y producción. Si permites credenciales, no utilices el comodín *. CORS no autentica, no protege clientes fuera del navegador y no reemplaza HTTPS ni autorización.','from fastapi.middleware.cors import CORSMiddleware\n\napp.add_middleware(\n    CORSMiddleware,\n    allow_origins=["http://localhost:5173", "https://app.example.com"],\n    allow_credentials=True,\n    allow_methods=["GET", "POST", "PATCH", "DELETE"],\n    allow_headers=["Authorization", "Content-Type"],\n)','<pre style="padding:16px;background:#0f172a;color:#a7f3d0">Origen permitido: https://app.example.com</pre>','Configura los orígenes desde el entorno y revisa dominios de vista previa antes de autorizarlos.'),
    B('Pruebas','TestClient y sustitución de dependencias','TestClient ejecuta solicitudes contra la aplicación sin levantar un servidor externo. Sustituye get_db por una base aislada de prueba y revierte o recrea datos entre casos. Comprueba estado, cuerpo y efectos persistidos. Nunca apuntes las pruebas automáticas a la base de producción.','from fastapi.testclient import TestClient\nfrom app.main import app\n\nclient = TestClient(app)\n\ndef test_health():\n    response = client.get("/health")\n    assert response.status_code == 200\n    assert response.json() == {"status": "ok"}\n\ndef test_create_product():\n    response = client.post("/api/v1/products", json={\n        "sku": "KEY-01", "name": "Keyboard", "price": "49.90", "stock": 8\n    })\n    assert response.status_code == 201','<pre style="padding:16px;background:#0f172a;color:#a7f3d0">health ✓\ncreate product ✓\nconflict ✓\nnot found ✓</pre>','Prueba también validación, conflicto, autorización y rollback, no solamente el caso exitoso.'),
    B('Observabilidad','Logs, errores y salud','Registra método, ruta, estado, duración e identificador de solicitud sin incluir credenciales o datos sensibles. Un manejador global puede convertir errores inesperados en una respuesta estable y conservar detalles en logs internos. Separa liveness del proceso y readiness de dependencias como PostgreSQL.','GET /health/live  → proceso responde\nGET /health/ready → consulta ligera a PostgreSQL\n\nLog estructurado:\n{\n  "request_id": "...",\n  "method": "GET",\n  "path": "/api/v1/products",\n  "status": 200,\n  "duration_ms": 18\n}','<pre style="padding:16px;background:#0f172a;color:#bae6fd">request_id · método · ruta · estado · duración</pre>','No registres Authorization, contraseñas, tokens, cadenas de conexión ni cuerpos sensibles.'),
    B('Contenedores','API y PostgreSQL con Compose','Compose puede ejecutar servicios reproducibles en desarrollo: api depende de db y ambos comparten una red interna. Un volumen conserva los datos de PostgreSQL. depends_on no garantiza que la base esté lista; configura healthcheck y reintentos. Los secretos de producción no pertenecen al archivo versionado.','services:\n  db:\n    image: postgres:17\n    environment:\n      POSTGRES_DB: app_db\n      POSTGRES_USER: app_user\n      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD}\n    volumes:\n      - pgdata:/var/lib/postgresql/data\n    healthcheck:\n      test: ["CMD-SHELL", "pg_isready -U app_user -d app_db"]\n  api:\n    build: .\n    env_file: .env\n    depends_on:\n      db:\n        condition: service_healthy\nvolumes:\n  pgdata:','<pre style="padding:16px;background:#0f172a;color:#86efac">db healthy → migrations → api ready</pre>','Fija versiones de imágenes y prepara copias de seguridad antes de considerar persistente el volumen.'),
    B('Despliegue','Migrar, ejecutar y verificar','El despliegue instala dependencias bloqueadas, configura secretos, ejecuta migraciones una sola vez y arranca la API con un comando de producción. El número de workers debe respetar conexiones y memoria disponibles. Después verifica readiness, documentación según política, CORS, TLS, logs, métricas y una operación CRUD.','pytest\nalembic upgrade head\nfastapi run app/main.py\n\n# Verificación\ncurl https://api.example.com/health/ready\n\n# Flujo de reversión\n1. detener nueva versión\n2. restaurar aplicación compatible\n3. revertir esquema solo si la migración lo permite','<pre style="padding:16px;background:#0f172a;color:#a7f3d0">tests ✓ migrations ✓ readiness ✓ CRUD ✓</pre>','Diseña migraciones compatibles hacia atrás cuando necesites despliegues sin interrupción.')
  ]);

  const backendRoute=[
    {
      title:'Backend FastAPI · Introducción',
      milestone:B('Proyecto','Hito 1 · Definir qué construiremos','La primera fase deja escrito el propósito del sistema antes de crear tecnología: Ana necesita consultar productos, registrar mercancía y confirmar ventas sin permitir stock negativo. También define qué herramientas ocuparán cada parte. Esta ficha se conserva como referencia para decidir si cada lección posterior acerca el proyecto a ese resultado.','PROYECTO: Tienda de Ana\n\nFrontend: React + Tailwind\nBackend: FastAPI\nBase de datos: PostgreSQL\n\nFunciones finales:\n[ ] consultar productos\n[ ] registrar mercancía\n[ ] actualizar precios\n[ ] crear ventas\n[ ] descontar stock de forma segura','<section style="font-family:system-ui;padding:18px;background:#eff6ff;border:1px solid #93c5fd;border-radius:14px"><strong>Fase 1 de 11</strong><h2>Proyecto definido</h2><p>Ya sabemos qué construiremos y con qué herramientas.</p></section>','No crees tablas ni componentes todavía; primero comprueba que puedes explicar el objetivo con palabras cotidianas.'),
    },
    {
      title:'Backend FastAPI · Armar el proyecto',
      milestone:B('Proyecto','Hito 3 · Confirmar la estructura vacía','Después de crear las carpetas desde el Explorador de VS Code, el backend tiene un lugar claro para configuración, HTTP, persistencia, reglas y pruebas. Todavía puede haber archivos vacíos; el logro de esta fase es que el árbol coincida y que entiendas qué responsabilidad recibirá cada parte durante las fases siguientes.','COMPROBAR EN EL EXPLORADOR\n[x] app/main.py\n[x] app/core/config.py\n[x] app/db/session.py\n[x] app/models/\n[x] app/schemas/\n[x] app/repositories/\n[x] app/services/\n[x] app/api/routes/\n[x] migrations/versions/\n[x] tests/\n[x] .env.example y .gitignore','<section style="font-family:system-ui;padding:18px;background:#f0fdf4;border:1px solid #86efac;border-radius:14px"><strong>Fase 3 de 11</strong><h2>Estructura preparada ✓</h2></section>','No llenes todos los archivos a la vez; la ruta indicará cuál abrir y completar en cada fase.'),
    },
    {
      title:'Backend FastAPI · Preparación',
      milestone:B('Proyecto','Hito 4 · Ejecutar la primera API','Esta fase convierte la estructura vacía en un programa ejecutable. El entorno virtual contiene dependencias, config.py puede leer variables y main.py crea FastAPI con una ruta de salud. La respuesta de /health confirma solamente que Python y la API funcionan; la conexión con PostgreSQL será el siguiente avance.','ARCHIVOS COMPLETADOS\napp/main.py\napp/core/config.py\nrequirements.txt\n.gitignore\n.env.example\n\nCOMPROBACIÓN\nGET http://127.0.0.1:8000/health\n→ 200 {"status": "ok"}\n\nSIGUIENTE\nInstalar y conectar PostgreSQL','<section style="font-family:system-ui;padding:18px;background:#eef2ff;border:1px solid #a5b4fc;border-radius:14px"><strong>Fase 4 de 11</strong><h2>FastAPI responde ✓</h2><p>La base de datos todavía no participa.</p></section>','No continúes si /health falla; corrige primero entorno, importación de app o ubicación de main.py.'),
    },
    {
      title:'Backend FastAPI · Instalar PostgreSQL',
      milestone:B('Proyecto','Hito 5 · Conectar la base de la tienda','PostgreSQL ya está instalado y la aplicación utiliza tienda_user para acceder a tienda_db. La URL privada llega desde .env, session.py construye el engine y /health/ready ejecuta SELECT 1. Tener /health y /health/ready separadas permite comprobar que FastAPI funciona y que también puede comunicarse con la base.','ARCHIVOS COMPLETADOS\n.env\napp/db/session.py\napp/api/routes/health.py\n\nPOSTGRESQL\ntienda_user → tienda_db\n\nCOMPROBACIONES\nGET /health       → {"status": "ok"}\nGET /health/ready → {"database": "ready"}\n\nSIGUIENTE\nDefinir el contrato HTTP de productos','<section style="font-family:system-ui;padding:18px;background:#ecfdf5;border:1px solid #6ee7b7;border-radius:14px"><strong>Fase 5 de 11</strong><h2>PostgreSQL conectado ✓</h2></section>','No uses el usuario postgres en DATABASE_URL y no subas .env al repositorio.'),
    },
    {
      title:'Backend FastAPI · API',
      milestone:B('Proyecto','Hito 6 · Probar el contrato en /docs','Los schemas y routers describen cómo entran y salen los productos aunque todavía no se haya completado toda la persistencia. Swagger UI permite enviar ejemplos, observar validaciones 422 y confirmar nombres, tipos y estados HTTP. Este contrato será respetado por el CRUD y consumido después por React, evitando que cada capa espere un formato diferente.','ARCHIVOS COMPLETADOS\napp/schemas/product.py\napp/api/routes/products.py\napp/main.py → include_router\n\nPROBAR EN /docs\nGET  /api/v1/products\nPOST /api/v1/products\nPATCH /api/v1/products/{id}\nDELETE /api/v1/products/{id}\n\nVALIDAR\nprecio negativo → 422\nstock negativo  → 422','<section style="font-family:system-ui;padding:18px;background:#eff6ff;border:1px solid #60a5fa;border-radius:14px"><strong>Fase 6 de 11</strong><h2>Contrato API visible ✓</h2></section>','Ajusta ahora los nombres del JSON; cambiarlos después de construir React obliga a modificar ambos lados.'),
    },
    {
      title:'Backend FastAPI · PostgreSQL',
      milestone:B('Proyecto','Hito 7 · Crear las tablas mediante migraciones','Los modelos Product, Sale y SaleItem representan el inventario y el historial. Alembic genera una revisión que debe leerse antes de aplicarse; upgrade crea las tablas en tienda_db y current confirma la revisión activa. Desde este punto la estructura de datos ya no depende de crear tablas manualmente al arrancar FastAPI.','ARCHIVOS COMPLETADOS\napp/db/base.py\napp/models/product.py\napp/models/sale.py\nmigrations/env.py\nmigrations/versions/...create_store_tables.py\n\nCOMPROBACIÓN\nalembic upgrade head\nalembic current\n\nPOSTGRESQL\nproducts\nsales\nsale_items','<section style="font-family:system-ui;padding:18px;background:#f5f3ff;border:1px solid #c4b5fd;border-radius:14px"><strong>Fase 7 de 11</strong><h2>Esquema creado ✓</h2></section>','Abre la migración y confirma columnas, restricciones y claves antes de ejecutar upgrade.'),
    },
    {
      title:'Backend FastAPI · CRUD',
      milestone:B('Proyecto','Hito 8 · Guardar productos y ventas reales','Los routers ya llaman servicios y repositorios usando una sesión por solicitud. Crear, listar, consultar, modificar y eliminar productos afecta tienda_db; registrar una venta crea su historial y descuenta existencias en una sola transacción. Las pruebas comprueban éxito, validación, ausencia, conflicto y rollback antes de conectar una pantalla.','ARCHIVOS COMPLETADOS\napp/repositories/products.py\napp/repositories/sales.py\napp/services/products.py\napp/services/sales.py\napp/api/routes/products.py\napp/api/routes/sales.py\ntests/test_products.py\ntests/test_sales.py\n\nPRUEBA FINAL EN /docs\n1. crear Pan con stock 20\n2. vender 2 panes\n3. consultar Pan → stock 18','<section style="font-family:system-ui;padding:18px;background:#ecfdf5;border:1px solid #34d399;border-radius:14px"><strong>Fase 8 de 11</strong><h2>Backend funcional ✓</h2><p>Los datos sobreviven al reinicio.</p></section>','No conectes React hasta que el flujo crear producto → vender → consultar stock funcione directamente en /docs.'),
    },
    {
      title:'Backend FastAPI · React + Tailwind',
      milestone:B('Proyecto','Hito 9 · Operar la tienda desde React','La interfaz React reemplaza las pruebas manuales cotidianas: carga el inventario, registra mercancía, forma un carrito y confirma ventas. Tailwind presenta estados de carga, error, vacío y éxito. FastAPI autoriza el origen del frontend mediante CORS y continúa siendo responsable de validar y calcular el resultado definitivo.','FLUJO COMPLETO\n1. React solicita GET /products\n2. Ana agrega Pan al carrito\n3. React envía POST /sales\n4. FastAPI valida y guarda\n5. PostgreSQL confirma la transacción\n6. React recarga GET /products\n7. La pantalla muestra stock actualizado\n\nRESULTADO\n2 panes vendidos: 20 → 18','<section style="font-family:system-ui;padding:18px;background:#f0fdfa;border:1px solid #5eead4;border-radius:14px"><strong>Fase 9 de 11</strong><h2>Aplicación full stack ✓</h2></section>','Comprueba también el flujo con stock insuficiente y muestra el mensaje de FastAPI cerca del carrito.'),
    },
    {
      title:'Backend FastAPI · Patrones de diseño',
      milestone:B('Proyecto','Hito 10 · Refactorizar sin cambiar el resultado','Con la aplicación ya funcionando, ahora los patrones se aplican sobre problemas observados: el servicio concentra la venta, Repository reúne consultas, Strategy separa descuentos y la transacción protege el conjunto. Las pruebas deben continuar pasando antes y después del refactor; si un patrón no mejora claridad o cambio, se conserva la solución directa.','ANTES\nAplicación funcional + pruebas verdes\n\nREFACTORIZAR\nrouter → service → repository\n descuento → strategy\n proveedor → adapter\n venta → transaction\n\nDESPUÉS\nMismas respuestas HTTP\nMismos cambios en PostgreSQL\nMisma interfaz React\nPruebas todavía verdes','<section style="font-family:system-ui;padding:18px;background:#fffbeb;border:1px solid #fbbf24;border-radius:14px"><strong>Fase 10 de 11</strong><h2>Código organizado ✓</h2></section>','Refactoriza un patrón por vez y ejecuta la prueba relacionada; no cambies arquitectura y comportamiento simultáneamente.'),
    },
    {
      title:'Backend FastAPI · Producción',
      milestone:B('Proyecto','Hito 11 · Entregar el proyecto completo','La fase final protege y verifica lo construido: autenticación y permisos, CORS por entorno, pruebas aisladas, migraciones controladas, logs seguros y comprobaciones de salud. El frontend genera su build y el backend arranca con configuración de producción. El proyecto está terminado cuando otro equipo puede instalarlo siguiendo README sin conocer tu computadora.','LISTA DE ENTREGA\n[x] React + Tailwind genera build\n[x] FastAPI ejecuta pruebas\n[x] PostgreSQL usa migraciones\n[x] secretos fuera de Git\n[x] CORS con orígenes exactos\n[x] /health y /health/ready\n[x] logs sin credenciales\n[x] README de instalación\n[x] crear producto y venta verificados\n\nRESULTADO\nTienda de Ana lista para desplegar','<section style="font-family:system-ui;padding:20px;background:#0f172a;color:white;border-radius:14px"><strong>Fase 11 de 11</strong><h2 style="color:#86efac">Proyecto completo ✓</h2><p>React + Tailwind + FastAPI + PostgreSQL</p></section>','Entrega solamente después de ejecutar pruebas, migraciones y el flujo completo en un entorno limpio.'),
    },
  ];

  const buildSteps={
    'Backend FastAPI · Introducción':B('Construcción guiada','Paso 1 · Escribir el objetivo en README.md','Abre README.md en la raíz del proyecto y reemplaza su contenido por esta ficha inicial. Todavía no escribimos Python: primero dejamos claro qué problema cotidiano resolverá la aplicación, qué tecnologías usará y cuál será el resultado final. En las fases siguientes ampliarás este mismo archivo; no crearás otro README.','# Tienda de Ana\n\nAplicación para consultar productos, registrar mercancía y vender sin permitir stock negativo.\n\n## Tecnologías\n- React y Tailwind CSS\n- FastAPI y Python\n- PostgreSQL\n\n## Resultado esperado\nAna podrá crear productos, actualizar precios y registrar ventas desde el navegador.','<section style="font-family:system-ui;padding:18px;background:#eff6ff;border:1px solid #60a5fa;border-radius:14px"><small>README.md</small><h2>1. Proyecto documentado</h2><p>Objetivo → tecnologías → resultado</p></section>','Guarda README.md y comprueba que puedes explicar el proyecto sin mencionar todavía carpetas o comandos.'),
    'Backend FastAPI · Caso cotidiano':B('Construcción guiada','Paso 2 · Agregar requisitos a README.md','Vuelve a abrir README.md y agrega este bloque al final, sin borrar la introducción. Cada historia expresa quién necesita algo, qué acción realizará y qué resultado observará. Debajo relacionamos esas acciones con las rutas que construiremos, de modo que el código posterior responda a una necesidad concreta.','## Historias de usuario\n- Como Ana, quiero ver el inventario para saber qué puedo vender.\n- Como Ana, quiero registrar mercancía para actualizar existencias.\n- Como Ana, quiero vender productos sin dejar el stock negativo.\n\n## API prevista\n- GET /api/v1/products: listar productos\n- POST /api/v1/products: registrar producto\n- PATCH /api/v1/products/{id}: editar producto\n- POST /api/v1/sales: registrar venta','<section style="font-family:system-ui;padding:18px;background:#fffbeb;border:1px solid #f59e0b;border-radius:14px"><small>README.md</small><h2>2. Historia convertida en rutas</h2></section>','No agregues una ruta si no puedes relacionarla con una acción que Ana necesita realizar.'),
    'Backend FastAPI · Armar el proyecto':B('Construcción guiada','Paso 3 · Identificar los paquetes de Python','En los archivos __init__.py escribe una frase breve que explique la responsabilidad de cada paquete. Estos archivos permiten reconocer la estructura como paquetes de Python y hacen visible para qué servirá cada carpeta. Los demás archivos pueden permanecer vacíos hasta que su fase indique exactamente qué contenido recibirán.','# app/__init__.py\n"""Aplicación backend de la tienda de Ana."""\n\n# app/api/__init__.py\n"""Rutas y dependencias HTTP."""\n\n# app/api/routes/__init__.py\n"""Endpoints agrupados por recurso."""\n\n# app/models/__init__.py\n"""Modelos persistidos en PostgreSQL."""\n\n# app/schemas/__init__.py\n"""Datos de entrada y salida de la API."""','<section style="font-family:system-ui;padding:18px;background:#f0fdf4;border:1px solid #4ade80;border-radius:14px"><small>Explorador de archivos</small><h2>3. Cada carpeta tiene una función</h2><p>api · models · schemas · services · repositories</p></section>','No copies lógica dentro de __init__.py; por ahora solamente documentan el propósito de los paquetes.'),
    'Backend FastAPI · Preparación':B('Construcción guiada','Paso 4 · Crear la primera API ejecutable','Completa primero requirements.txt y después reemplaza app/main.py con el código mostrado. La ruta /health no consulta la base de datos: sirve para comprobar que el entorno, las dependencias y el punto de entrada funcionan. Añade también las reglas mínimas de .gitignore antes de crear archivos con secretos.','# requirements.txt\nfastapi[standard]\nsqlalchemy\npsycopg[binary]\npydantic-settings\nalembic\npytest\nhttpx\n\n# app/main.py\nfrom fastapi import FastAPI\n\napp = FastAPI(title="Tienda de Ana", version="1.0.0")\n\n@app.get("/health", tags=["health"])\ndef health():\n    return {"status": "ok"}\n\n# .gitignore\n.venv/\n__pycache__/\n.env\n.pytest_cache/','<section style="font-family:system-ui;padding:18px;background:#eef2ff;border:1px solid #818cf8;border-radius:14px"><small>app/main.py</small><h2>4. GET /health</h2><code>200 {"status":"ok"}</code></section>','Instala requirements.txt, ejecuta FastAPI y no avances hasta obtener 200 en /health.'),
    'Backend FastAPI · Instalar PostgreSQL':B('Construcción guiada','Paso 5 · Conectar FastAPI con tienda_db','Crea .env con tu clave real y .env.example con un valor ficticio. Después completa config.py y session.py; finalmente crea el router de disponibilidad e inclúyelo en main.py. Así cada archivo recibe una sola responsabilidad: configuración, sesiones, comprobación HTTP y ensamblaje de la aplicación.','# .env\nDATABASE_URL=postgresql+psycopg://tienda_user:TU_CLAVE@localhost:5432/tienda_db\n\n# app/core/config.py\nfrom functools import lru_cache\nfrom pydantic_settings import BaseSettings, SettingsConfigDict\n\nclass Settings(BaseSettings):\n    database_url: str\n    model_config = SettingsConfigDict(env_file=".env")\n\n@lru_cache\ndef get_settings():\n    return Settings()\n\n# app/db/session.py\nfrom sqlalchemy import create_engine\nfrom sqlalchemy.orm import sessionmaker\nfrom app.core.config import get_settings\n\nengine = create_engine(get_settings().database_url, pool_pre_ping=True)\nSessionLocal = sessionmaker(bind=engine, expire_on_commit=False)\n\ndef get_db():\n    with SessionLocal() as session:\n        yield session\n\n# app/api/routes/health.py\nfrom fastapi import APIRouter\nfrom sqlalchemy import text\nfrom app.db.session import engine\n\nrouter = APIRouter(prefix="/health", tags=["health"])\n\n@router.get("/ready")\ndef ready():\n    with engine.connect() as connection:\n        connection.execute(text("SELECT 1"))\n    return {"database": "ready"}\n\n# Agregar en app/main.py\nfrom app.api.routes import health as health_routes\napp.include_router(health_routes.router)','<section style="font-family:system-ui;padding:18px;background:#ecfdf5;border:1px solid #34d399;border-radius:14px"><small>.env → session.py → health.py</small><h2>5. PostgreSQL responde</h2><code>GET /health/ready</code></section>','No copies TU_CLAVE en .env.example ni en capturas; confirma también que .env aparece ignorado por Git.'),
    'Backend FastAPI · API':B('Construcción guiada','Paso 6 · Definir el contrato de productos','Crea el schema antes del router: así FastAPI sabe qué campos aceptar, cómo validarlos y qué mostrar en Swagger. Luego crea products.py con una lista temporal para probar el contrato sin mezclar todavía SQL. Al final incluye el router en main.py; esta lista será reemplazada por PostgreSQL en la fase de CRUD.','# app/schemas/product.py\nfrom decimal import Decimal\nfrom pydantic import BaseModel, ConfigDict, Field\n\nclass ProductCreate(BaseModel):\n    sku: str = Field(min_length=2, max_length=40)\n    name: str = Field(min_length=2, max_length=120)\n    price: Decimal = Field(gt=0)\n    stock: int = Field(ge=0)\n\nclass ProductRead(ProductCreate):\n    id: int\n    model_config = ConfigDict(from_attributes=True)\n\n# app/api/routes/products.py\nfrom fastapi import APIRouter\nfrom app.schemas.product import ProductCreate\n\nrouter = APIRouter(prefix="/products", tags=["products"])\nproducts: list[dict] = []\n\n@router.get("")\ndef list_products():\n    return products\n\n@router.post("", status_code=201)\ndef create_product(data: ProductCreate):\n    product = {"id": len(products) + 1, **data.model_dump()}\n    products.append(product)\n    return product\n\n# Agregar en app/main.py\nfrom app.api.routes import products\napp.include_router(products.router, prefix="/api/v1")','<section style="font-family:system-ui;padding:18px;background:#eff6ff;border:1px solid #3b82f6;border-radius:14px"><small>schemas/product.py + routes/products.py</small><h2>6. Contrato visible en /docs</h2></section>','Reiniciar la API vacía la lista temporal; es intencional y demuestra por qué la siguiente fase necesita persistencia.'),
    'Backend FastAPI · PostgreSQL':B('Construcción guiada','Paso 7 · Convertir Product en una tabla','Define una base compartida, importa los modelos desde db/base.py y crea Product con restricciones equivalentes a las reglas del schema. Luego señala esa metadata en migrations/env.py. Alembic podrá comparar los modelos con PostgreSQL y generar una migración revisable, en lugar de crear tablas ocultamente al iniciar la API.','# app/db/base_class.py\nfrom sqlalchemy.orm import DeclarativeBase\n\nclass Base(DeclarativeBase):\n    pass\n\n# app/models/product.py\nfrom decimal import Decimal\nfrom sqlalchemy import CheckConstraint, Numeric, String\nfrom sqlalchemy.orm import Mapped, mapped_column\nfrom app.db.base_class import Base\n\nclass Product(Base):\n    __tablename__ = "products"\n    __table_args__ = (\n        CheckConstraint("price > 0"),\n        CheckConstraint("stock >= 0"),\n    )\n    id: Mapped[int] = mapped_column(primary_key=True)\n    sku: Mapped[str] = mapped_column(String(40), unique=True, index=True)\n    name: Mapped[str] = mapped_column(String(120))\n    price: Mapped[Decimal] = mapped_column(Numeric(10, 2))\n    stock: Mapped[int]\n\n# app/db/base.py\nfrom app.db.base_class import Base\nfrom app.models.product import Product\n\n# migrations/env.py: reemplazar target_metadata\nfrom app.db.base import Base\ntarget_metadata = Base.metadata','<section style="font-family:system-ui;padding:18px;background:#f5f3ff;border:1px solid #8b5cf6;border-radius:14px"><small>modelo → metadata → migración</small><h2>7. Tabla products preparada</h2></section>','Revisa el archivo generado por Alembic antes de ejecutar upgrade head; no uses create_all junto con migraciones.'),
    'Backend FastAPI · CRUD':B('Construcción guiada','Paso 8 · Sustituir la lista por PostgreSQL','Crea primero el repositorio, que conoce SQLAlchemy; después el servicio, que expresa el caso de uso; por último reemplaza el router temporal. El endpoint ya no guarda en una lista: recibe una sesión con Depends, delega la operación y devuelve un objeto persistido. Repite el mismo recorrido para consultar, editar y eliminar con las fichas de esta fase.','# app/repositories/products.py\nfrom sqlalchemy import select\nfrom sqlalchemy.orm import Session\nfrom app.models.product import Product\n\ndef list_all(db: Session):\n    return db.scalars(select(Product).order_by(Product.id)).all()\n\ndef create(db: Session, data):\n    product = Product(**data.model_dump())\n    db.add(product)\n    db.commit()\n    db.refresh(product)\n    return product\n\n# app/services/products.py\nfrom sqlalchemy.orm import Session\nfrom app.repositories import products as repository\n\ndef list_products(db: Session):\n    return repository.list_all(db)\n\ndef create_product(db: Session, data):\n    return repository.create(db, data)\n\n# Reemplazar app/api/routes/products.py\nfrom typing import Annotated\nfrom fastapi import APIRouter, Depends\nfrom sqlalchemy.orm import Session\nfrom app.db.session import get_db\nfrom app.schemas.product import ProductCreate, ProductRead\nfrom app.services import products as service\n\nrouter = APIRouter(prefix="/products", tags=["products"])\nDbSession = Annotated[Session, Depends(get_db)]\n\n@router.get("", response_model=list[ProductRead])\ndef list_products(db: DbSession):\n    return service.list_products(db)\n\n@router.post("", response_model=ProductRead, status_code=201)\ndef create_product(data: ProductCreate, db: DbSession):\n    return service.create_product(db, data)','<section style="font-family:system-ui;padding:18px;background:#ecfdf5;border:1px solid #10b981;border-radius:14px"><small>router → service → repository → PostgreSQL</small><h2>8. Los productos persisten</h2></section>','Prueba crear y listar antes de implementar PATCH y DELETE; así cualquier error queda limitado a pocos archivos.'),
    'Backend FastAPI · React + Tailwind':B('Construcción guiada','Paso 9 · Mostrar el inventario en React','Centraliza la URL y la solicitud en services/api.js; App.jsx solamente controla estado y presentación. Reemplaza su contenido por el componente mostrado y conserva index.css con las directivas de Tailwind. La pantalla ya consume el GET persistente de la fase anterior y muestra carga, error, vacío o productos.','# frontend/src/services/api.js\nconst API_URL = import.meta.env.VITE_API_URL ?? "http://127.0.0.1:8000/api/v1";\n\nexport async function getProducts() {\n  const response = await fetch(`${API_URL}/products`);\n  if (!response.ok) throw new Error("No se pudo cargar el inventario");\n  return response.json();\n}\n\n# frontend/src/App.jsx\nimport { useEffect, useState } from "react";\nimport { getProducts } from "./services/api";\n\nexport default function App() {\n  const [products, setProducts] = useState([]);\n  const [error, setError] = useState("");\n\n  useEffect(() => {\n    getProducts().then(setProducts).catch(error => setError(error.message));\n  }, []);\n\n  return <main className="min-h-screen bg-slate-950 p-8 text-white">\n    <h1 className="text-3xl font-bold text-emerald-400">Inventario</h1>\n    {error && <p className="mt-4 text-red-300">{error}</p>}\n    <ul className="mt-6 grid gap-4 md:grid-cols-2">\n      {products.map(product => <li className="rounded-xl bg-slate-800 p-4" key={product.id}>\n        <strong>{product.name}</strong><p>Stock: {product.stock}</p>\n      </li>)}\n    </ul>\n  </main>;\n}\n\n# frontend/src/index.css\n@import "tailwindcss";','<section style="font-family:system-ui;padding:18px;background:#0f172a;color:white;border:1px solid #2dd4bf;border-radius:14px"><small>React + Tailwind</small><h2 style="color:#5eead4">9. Inventario visible</h2><p>Producto · precio · stock</p></section>','Configura VITE_API_URL y CORS; si la API falla, muestra el error en la interfaz en vez de dejar una pantalla vacía.'),
    'Backend FastAPI · Patrones de diseño':B('Construcción guiada','Paso 10 · Extraer una regla que realmente cambia','Con el flujo funcionando, extrae solamente la política de descuento. Define un protocolo y dos estrategias; el servicio recibe la estrategia sin conocer su fórmula. Esta modificación ilustra Strategy sobre una necesidad real y mantiene el router, el repositorio y PostgreSQL sin cambios. Ejecuta las pruebas antes y después para confirmar el mismo resultado.','# app/services/discounts.py\nfrom decimal import Decimal\nfrom typing import Protocol\n\nclass Discount(Protocol):\n    def apply(self, subtotal: Decimal) -> Decimal: ...\n\nclass NoDiscount:\n    def apply(self, subtotal: Decimal) -> Decimal:\n        return subtotal\n\nclass PercentageDiscount:\n    def __init__(self, percent: Decimal):\n        self.percent = percent\n\n    def apply(self, subtotal: Decimal) -> Decimal:\n        return subtotal * (Decimal("1") - self.percent / Decimal("100"))\n\n# app/services/sales.py\nfrom app.services.discounts import Discount\n\ndef calculate_total(subtotal, discount: Discount):\n    return discount.apply(subtotal)','<section style="font-family:system-ui;padding:18px;background:#fffbeb;border:1px solid #f59e0b;border-radius:14px"><small>sales.py usa Discount</small><h2>10. Regla intercambiable</h2><p>Sin descuento ↔ descuento porcentual</p></section>','No conviertas cada función en un patrón; extrae una abstracción solamente cuando exista más de una política real.'),
    'Backend FastAPI · Producción':B('Construcción guiada','Paso 11 · Dejar una entrega reproducible','Añade una prueba de salud, documenta las variables sin secretos y completa README.md con el orden de arranque. Otro equipo debe poder clonar, configurar, migrar, probar y ejecutar el proyecto siguiendo esos archivos. La entrega conserva todo lo construido: no reemplaza el proyecto por una configuración distinta.','# tests/test_health.py\nfrom fastapi.testclient import TestClient\nfrom app.main import app\n\nclient = TestClient(app)\n\ndef test_health():\n    response = client.get("/health")\n    assert response.status_code == 200\n    assert response.json() == {"status": "ok"}\n\n# .env.example\nDATABASE_URL=postgresql+psycopg://tienda_user:CHANGE_ME@localhost:5432/tienda_db\n\n# Agregar al final de README.md\n## Ejecutar el proyecto\n1. Crear y activar el entorno virtual.\n2. Instalar requirements.txt.\n3. Copiar .env.example como .env y configurar la conexión.\n4. Ejecutar alembic upgrade head.\n5. Ejecutar pytest.\n6. Iniciar FastAPI y después React.\n7. Verificar /health/ready y una venta completa.','<section style="font-family:system-ui;padding:20px;background:#0f172a;color:white;border-radius:14px"><small>README + pruebas + variables</small><h2 style="color:#86efac">11. Proyecto reproducible</h2><p>configurar → migrar → probar → ejecutar</p></section>','Haz una instalación desde cero siguiendo solamente README; cualquier paso que recuerdes pero no esté escrito todavía falta en la entrega.'),
  };

  const buildGuides={
    'Backend FastAPI · Introducción':[
      ['Reemplazar','README.md','Escribe aquí el objetivo, las tecnologías y el resultado esperado.'],
    ],
    'Backend FastAPI · Armar el proyecto':[
      ['Crear','app/__init__.py','Identifica el paquete principal del backend.'],
      ['Crear','app/api/__init__.py','Identifica el paquete de la API.'],
      ['Crear','app/api/routes/__init__.py','Identifica el paquete de rutas.'],
      ['Crear','app/models/__init__.py','Identifica el paquete de modelos.'],
      ['Crear','app/schemas/__init__.py','Identifica el paquete de schemas.'],
    ],
    'Backend FastAPI · Preparación':[
      ['Crear','requirements.txt','Copia la lista de dependencias.'],
      ['Reemplazar','app/main.py','Deja la primera aplicación FastAPI y su ruta /health.'],
      ['Agregar','.gitignore','Añade estas reglas sin borrar otras reglas existentes.'],
    ],
    'Backend FastAPI · Instalar PostgreSQL':[
      ['Crear','.env','Coloca la conexión real y cambia TU_CLAVE. No subas este archivo.'],
      ['Crear','.env.example','Copia la misma variable con una contraseña ficticia.'],
      ['Reemplazar','app/core/config.py','Configura la lectura de DATABASE_URL.'],
      ['Reemplazar','app/db/session.py','Configura engine, SessionLocal y get_db.'],
      ['Crear','app/api/routes/health.py','Añade la comprobación de PostgreSQL.'],
      ['Agregar','app/main.py','Añade el import y app.include_router al código de la fase anterior.'],
    ],
    'Backend FastAPI · API':[
      ['Crear','app/schemas/product.py','Define ProductCreate y ProductRead.'],
      ['Crear','app/api/routes/products.py','Añade primero el router temporal de productos.'],
      ['Agregar','app/main.py','Importa products e incluye su router debajo del router de salud.'],
    ],
    'Backend FastAPI · PostgreSQL':[
      ['Crear','app/db/base_class.py','Define la clase Base compartida.'],
      ['Crear','app/models/product.py','Convierte Product en un modelo de SQLAlchemy.'],
      ['Crear','app/db/base.py','Importa Base y todos los modelos.'],
      ['Reemplazar','migrations/env.py','Sustituye target_metadata por Base.metadata y conserva el resto de Alembic.'],
    ],
    'Backend FastAPI · CRUD':[
      ['Crear','app/repositories/products.py','Coloca aquí únicamente las consultas a PostgreSQL.'],
      ['Crear','app/services/products.py','Coloca aquí las operaciones del caso de uso.'],
      ['Reemplazar','app/api/routes/products.py','Quita la lista temporal y usa la sesión y el servicio.'],
    ],
    'Backend FastAPI · React + Tailwind':[
      ['Crear','frontend/src/services/api.js','Centraliza aquí la dirección y las solicitudes HTTP.'],
      ['Reemplazar','frontend/src/App.jsx','Muestra los productos obtenidos desde FastAPI.'],
      ['Reemplazar','frontend/src/index.css','Deja la importación principal de Tailwind.'],
    ],
    'Backend FastAPI · Patrones de diseño':[
      ['Crear','app/services/discounts.py','Define las estrategias de descuento.'],
      ['Agregar','app/services/sales.py','Importa Discount y añade calculate_total sin borrar la venta existente.'],
    ],
    'Backend FastAPI · Producción':[
      ['Crear','tests/test_health.py','Añade la prueba automática de /health.'],
      ['Reemplazar','.env.example','Documenta la variable requerida sin una clave real.'],
      ['Agregar','README.md','Añade al final los pasos para instalar y ejecutar el proyecto.'],
    ],
  };

  const backendCaseIndex=sections.findIndex(section=>section.title==='Backend FastAPI · Caso cotidiano');
  if(backendCaseIndex>=0)sections.splice(backendCaseIndex,1);

  const backendStart=sections.findIndex(section=>section.title==='Backend FastAPI · Introducción');
  const orderedBackend=backendRoute.map((stage,index)=>{
    const section=sections.find(candidate=>candidate.title===stage.title);
    const buildStep=buildSteps[stage.title];
    buildStep.guide=buildGuides[stage.title];
    buildStep.name=buildStep.name.replace(/^Paso \d+/,`Paso ${index+1}`);
    buildStep.preview=buildStep.preview.replace(/(<h2(?: style="[^"]*")?>)\d+\./,`$1${index+1}.`);
    stage.milestone.name=stage.milestone.name.replace(/^Hito \d+/,`Hito ${index+1}`);
    stage.milestone.preview=stage.milestone.preview.replace(/Fase \d+ de \d+/,`Fase ${index+1} de ${backendRoute.length}`);
    section.description=`Fase ${index+1} de ${backendRoute.length}. ${section.description}`;
    section.items.unshift(buildStep);
    section.items.push(stage.milestone);
    return section;
  });
  sections.splice(backendStart,orderedBackend.length,...orderedBackend);

  buildNav();
  render();
})();
